```nim
## Backtracking as a pure generator: a search tree is described by two functions, `children`
## (the ways to extend a partial state) and `isSolution`, and `backtrack` returns every solution in
## depth-first, left-to-right order. Nothing is mutated by the caller; the only `var` is the list being
## collected inside the walk.
##
## Use it for constraint problems with a small search tree: permutations, combinations, n-queens,
## sudoku-like puzzles. Pruning lives in `children`: return only extensions that can still
## lead to a solution. When the number of solutions is huge or only one is needed, use
## `firstSolution`; when sub-problems repeat, switch to dynamic programming (`memoization`).
##
## The domain helpers refuse sizes whose answer would not be a sensible list (negative, or large
## enough to take minutes); the limits are exported constants.

import std/options

type
  Children*[S] = proc(s: S): seq[S] {.noSideEffect, raises: [].}
  Accept*[S] = proc(s: S): bool {.noSideEffect, raises: [].}

const
  maxPermutationSize*: int = 9
  maxCombinationSize*: int = 20
  maxQueensSize*: int = 10

func walk[S](s: S; children: Children[S]; accept: Accept[S]; found: var seq[S]) {.raises: [].} =
  if accept(s):
    found.add s
  for c in children(s):
    walk(c, children, accept, found)

func backtrack*[S](start: S; children: Children[S]; accept: Accept[S]): seq[S] {.raises: [].} =
  ## Every state reachable from `start` for which `accept` holds, in pre-order (TECH-BT-GEN-01,
  ## TECH-BT-GEN-02). The same arguments always give the same list.
  result = @[]
  walk(start, children, accept, result)

func firstWalk[S](s: S; children: Children[S]; accept: Accept[S]): Option[S] {.raises: [].} =
  if accept(s):
    return some(s)
  for c in children(s):
    let r = firstWalk(c, children, accept)
    if r.isSome:
      return r
  none(S)

func firstSolution*[S](start: S; children: Children[S]; accept: Accept[S]): Option[S] {.raises: [].} =
  ## The first element `backtrack` would return, without visiting the rest of the tree (TECH-BT-GEN-03).
  firstWalk(start, children, accept)

func permutations*(n: int): Option[seq[seq[int]]] {.raises: [].} =
  ## All orderings of 0 ..< n in lexicographic order; one empty ordering when n is 0. None when
  ## n < 0 or n > `maxPermutationSize` (TECH-BT-PERM-01 .. TECH-BT-PERM-03).
  if n < 0 or n > maxPermutationSize:
    return none(seq[seq[int]])
  func kids(s: seq[int]): seq[seq[int]] {.raises: [].} =
    result = @[]
    if s.len < n:
      for v in 0 ..< n:
        if v notin s:
          result.add s & @[v]
  func done(s: seq[int]): bool {.raises: [].} = s.len == n
  some(backtrack(newSeq[int](), kids, done))

func combinations*(n, k: int): Option[seq[seq[int]]] {.raises: [].} =
  ## All k-element subsets of 0 ..< n, each ascending, in lexicographic order. Empty when k > n.
  ## None when n or k is negative or n > `maxCombinationSize` (TECH-BT-COMB-01, TECH-BT-COMB-02).
  if n < 0 or k < 0 or n > maxCombinationSize:
    return none(seq[seq[int]])
  func kids(s: seq[int]): seq[seq[int]] {.raises: [].} =
    result = @[]
    if s.len < k:
      let first = if s.len == 0: 0 else: s[s.len - 1] + 1
      for v in first ..< n:
        if n - v >= k - s.len:      # enough values left to reach size k
          result.add s & @[v]
  func done(s: seq[int]): bool {.raises: [].} = s.len == k
  some(backtrack(newSeq[int](), kids, done))

func safeToPlace(cols: seq[int]; col: int): bool {.raises: [].} =
  let row = cols.len
  for r in 0 ..< row:
    if cols[r] == col or abs(cols[r] - col) == row - r:
      return false
  true

func nQueens*(n: int): Option[seq[seq[int]]] {.raises: [].} =
  ## All placements of n non-attacking queens on an n x n board, as the column of the queen in each
  ## row, in lexicographic order. n = 0 has one (empty) placement. None when n < 0 or n >
  ## `maxQueensSize` (TECH-BT-QUEENS-01, TECH-BT-QUEENS-02).
  if n < 0 or n > maxQueensSize:
    return none(seq[seq[int]])
  func kids(s: seq[int]): seq[seq[int]] {.raises: [].} =
    result = @[]
    if s.len < n:
      for c in 0 ..< n:
        if safeToPlace(s, c):
          result.add s & @[c]
  func done(s: seq[int]): bool {.raises: [].} = s.len == n
  some(backtrack(newSeq[int](), kids, done))
```

```nim
## Bellman-Ford: relax every arc, V - 1 times; a further improvement proves a negative cycle.
##
## Use it for shortest paths when weights may be negative, or to detect a negative cycle (an
## arbitrage loop, an impossible constraint set). It costs O(V * E), slower than `dijkstra`, which
## is the better choice when no weight is negative. A negative cycle reachable from the source
## makes "shortest" meaningless, so the error value carries such a cycle instead of a bogus tree.
## An undirected edge of negative weight is a negative cycle of two arcs. Distances are `int`.

import std/[algorithm, options]
import nimcs/fp/result
import nimcs/algo/graph

type
  BellmanFordFailure* = enum
    bfBadSource       ## the source is not a vertex
    bfNegativeCycle   ## a negative cycle is reachable from the source

  BellmanFordError* = object
    case kind*: BellmanFordFailure
    of bfBadSource: discard
    of bfNegativeCycle:
      cycle*: seq[int]    ## v0 -> v1 -> ... -> vk -> v0, listed once around, starting at its smallest vertex

func cycleThrough(parent: seq[int]; changed: int): seq[int] {.raises: [].} =
  ## `changed` improved on the last pass, so following predecessors from it enters a cycle
  ## within n steps; then the cycle is read off.
  var inside = changed
  for _ in 0 ..< parent.len:
    inside = parent[inside]
  var backwards = @[inside]
  var current = parent[inside]
  while current != inside:
    backwards.add current
    current = parent[current]
  backwards.reverse
  var at = 0
  for i, v in backwards:
    if v < backwards[at]: at = i
  # Start at the smallest vertex, so the report does not depend on where the walk landed.
  backwards[at .. ^1] & backwards[0 ..< at]

func bellmanFord*(g: Graph; source: int): Result[PathTree, BellmanFordError] {.raises: [].} =
  ## Shortest distances from `source` (GRAPH-BELLMAN-01), or a negative cycle reachable from it
  ## (GRAPH-BELLMAN-02).
  if not g.inRange(source):
    return err(PathTree, BellmanFordError(kind: bfBadSource))
  let n = g.vertexCount
  var dist = newSeq[int](n)
  var reached = newSeq[bool](n)
  var parent = newSeq[int](n)
  for v in 0 ..< n:
    parent[v] = -1
  reached[source] = true
  for pass in 1 .. n:
    var changed = -1
    for u in 0 ..< n:
      if not reached[u]: continue
      for a in g.neighbors(u):
        let candidate = dist[u] + a.weight
        if not reached[a.target] or candidate < dist[a.target]:
          reached[a.target] = true
          dist[a.target] = candidate
          parent[a.target] = u
          changed = a.target
    if changed < 0:
      break
    if pass == n:
      return err(PathTree, BellmanFordError(kind: bfNegativeCycle, cycle: cycleThrough(parent, changed)))
  var distances = newSeq[Option[int]](n)
  var parents = newSeq[Option[int]](n)
  for v in 0 ..< n:
    if reached[v]:
      distances[v] = some(dist[v])
    if parent[v] >= 0 and v != source:
      parents[v] = some(parent[v])
  ok(PathTree(source: source, dist: distances, parent: parents), BellmanFordError)
```

```nim
## Depth-first search, iterative: follow one branch as far as it goes, then back up.
##
## Use it for reachability, cycle detection, topological order (reverse postorder) and as the first
## pass of strongly connected components. It runs in O(V + E). The explicit stack means a path of
## a million vertices does not overflow the call stack. Neighbours are visited in the graph's
## order, so both orders are deterministic.

import nimcs/fp/result
import nimcs/algo/graph

type DfsOrder* = object
  ## Vertices in the order they were entered (preorder) and left (postorder).
  preorder*: seq[int]
  postorder*: seq[int]

func explore(g: Graph; start: int; visited: var seq[bool]; order: var DfsOrder) {.raises: [].} =
  ## Visits everything reachable from `start` that is not yet visited.
  var stack: seq[(int, int)]    # (vertex, index of its next neighbour to try)
  visited[start] = true
  order.preorder.add start
  stack.add (start, 0)
  while stack.len > 0:
    let (u, next) = stack[^1]
    let arcs = g.neighbors(u)
    if next < arcs.len:
      stack[^1] = (u, next + 1)
      let v = arcs[next].target
      if not visited[v]:
        visited[v] = true
        order.preorder.add v
        stack.add (v, 0)
    else:
      order.postorder.add u
      discard stack.pop

func dfs*(g: Graph; start: int): Result[DfsOrder, GraphError] {.raises: [].} =
  ## The vertices reachable from `start`, in preorder and postorder (GRAPH-DFS-01). Fails when
  ## `start` is not a vertex.
  if not g.inRange(start):
    return err(DfsOrder, geVertexOutOfRange)
  var visited = newSeq[bool](g.vertexCount)
  var order = DfsOrder()
  explore(g, start, visited, order)
  ok(order, GraphError)

func dfsForest*(g: Graph): DfsOrder {.raises: [].} =
  ## A search from vertex 0, then from the smallest vertex not yet visited, and so on, so every
  ## vertex appears exactly once in each order (GRAPH-DFS-02).
  var visited = newSeq[bool](g.vertexCount)
  for v in 0 ..< g.vertexCount:
    if not visited[v]:
      explore(g, v, visited, result)
```

```nim
## Dijkstra's algorithm: settle vertices in order of distance, always from the closest unsettled one.
##
## Use it for shortest paths on graphs whose weights are all non-negative (travel time, cost).
## A binary heap with lazy deletion gives O((V + E) log V). With a negative weight the greedy
## argument fails, so this refuses the graph; use `bellman_ford` instead. Distances are `int`
## sums of weights: the caller keeps them small enough not to overflow (an overflow is a Defect).

import std/[heapqueue, options]
import nimcs/fp/result
import nimcs/algo/graph

func dijkstra*(g: Graph; source: int): Result[PathTree, GraphError] {.raises: [].} =
  ## Shortest distances and predecessors from `source` (GRAPH-DIJKSTRA-01). Fails with
  ## `geVertexOutOfRange` for a bad source and `geNegativeWeight` when any arc is negative
  ## (GRAPH-DIJKSTRA-02). Unreachable vertices have distance none.
  if not g.inRange(source):
    return err(PathTree, geVertexOutOfRange)
  let n = g.vertexCount
  for u in 0 ..< n:
    for a in g.neighbors(u):
      if a.weight < 0:
        return err(PathTree, geNegativeWeight)
  var dist = newSeq[Option[int]](n)
  var parent = newSeq[Option[int]](n)
  var settled = newSeq[bool](n)
  var frontier = initHeapQueue[(int, int)]()    # (distance, vertex): ties go to the smaller vertex
  dist[source] = some(0)
  frontier.push (0, source)
  while frontier.len > 0:
    let (d, u) = frontier.pop
    if settled[u]: continue
    settled[u] = true
    for a in g.neighbors(u):
      let candidate = d + a.weight
      if dist[a.target].isNone or candidate < dist[a.target].get:
        dist[a.target] = some(candidate)
        parent[a.target] = some(u)
        frontier.push (candidate, a.target)
  ok(PathTree(source: source, dist: dist, parent: parent), GraphError)
```

```nim
## Divide and conquer: split the input, solve the halves, combine. Shown on the maximum-sum
## contiguous subarray, with Kadane's linear scan as the cross-check, and on the master theorem
## that says what a recurrence T(n) = a T(n/b) + Theta(n^d) costs.
##
## `maxSubarrayDc` solves the left half, the right half and the best subarray crossing the middle,
## and keeps the largest: T(n) = 2 T(n/2) + Theta(n) = Theta(n log n). `maxSubarrayKadane`
## does the same in Theta(n) by carrying the best sum ending at the current element. Prefer Kadane
## in practice; the divide-and-conquer form is the one that generalises (e.g. to a segment tree).
## Sums are assumed not to overflow `int`; that is the caller's precondition.

import std/options

type
  Subarray* = object
    ## The slice `xs[first .. last]` (both inclusive) with total `sum`.
    sum*, first*, last*: int

  MasterCase* = enum
    mcRoot      ## a < b^d: the work at the root dominates, T(n) = Theta(n^d)
    mcBalanced  ## a = b^d: every level costs the same, T(n) = Theta(n^d log n)
    mcLeaves    ## a > b^d: the leaves dominate, T(n) = Theta(n^(log_b a))

func maxSubarrayKadane*(xs: openArray[int]): Option[Subarray] {.raises: [].} =
  ## Best non-empty contiguous slice by one scan; none for empty input (TECH-DC-MAXSUB-01,
  ## TECH-DC-MAXSUB-04). On ties it keeps the first slice that reaches the maximum.
  if xs.len == 0:
    return none(Subarray)
  var best = Subarray(sum: xs[0], first: 0, last: 0)
  var cur = best
  for i in 1 ..< xs.len:
    if cur.sum < 0:
      cur = Subarray(sum: xs[i], first: i, last: i)
    else:
      cur = Subarray(sum: cur.sum + xs[i], first: cur.first, last: i)
    if cur.sum > best.sum:
      best = cur
  some(best)

func dcStep(xs: openArray[int]; lo, hi: int): Subarray {.raises: [].} =
  if lo == hi:
    return Subarray(sum: xs[lo], first: lo, last: lo)
  let mid = (lo + hi) div 2
  let left = dcStep(xs, lo, mid)
  let right = dcStep(xs, mid + 1, hi)
  var sum = 0
  var bestLeft = low(int)
  var from0 = mid
  for i in countdown(mid, lo):
    sum += xs[i]
    if sum > bestLeft:
      bestLeft = sum
      from0 = i
  sum = 0
  var bestRight = low(int)
  var to0 = mid + 1
  for i in mid + 1 .. hi:
    sum += xs[i]
    if sum > bestRight:
      bestRight = sum
      to0 = i
  result = left
  let across = Subarray(sum: bestLeft + bestRight, first: from0, last: to0)
  if across.sum > result.sum:
    result = across
  if right.sum > result.sum:
    result = right

func maxSubarrayDc*(xs: openArray[int]): Option[Subarray] {.raises: [].} =
  ## The same maximum by divide and conquer; none for empty input (TECH-DC-MAXSUB-02, TECH-DC-MAXSUB-04).
  ## The sum equals Kadane's; the slice may differ when several slices share the maximum.
  if xs.len == 0: none(Subarray)
  else: some(dcStep(xs, 0, xs.high))

func masterCase*(a, b, d: int): Option[MasterCase] {.raises: [].} =
  ## Which case of the master theorem applies to T(n) = a T(n/b) + Theta(n^d). None unless a >= 1,
  ## b >= 2 and d >= 0 (TECH-DC-MASTER-03). Compares a with b^d without ever forming an overflowing
  ## power (TECH-DC-MASTER-01, TECH-DC-MASTER-02).
  if a < 1 or b < 2 or d < 0:
    return none(MasterCase)
  var p = 1
  for _ in 1 .. d:
    if p > a div b:       # p * b > a: b^d exceeds a however large d is
      return some(mcRoot)
    p *= b
  if a < p: some(mcRoot)
  elif a == p: some(mcBalanced)
  else: some(mcLeaves)
```

```nim
## Edit (Levenshtein) distance: the least number of single-character insertions, deletions and
## substitutions that turn one string into another, together with a script that does it.
##
## Use it for fuzzy matching, spelling suggestions and diffs at character level. The script is
## a list of `EditOp` values, and `applyScript` replays it, which makes the result checkable.
## For a diff that never substitutes, use `lcs` (insert/delete distance = len a + len b - 2 lcs).

import std/options

type
  EditKind* = enum
    ekKeep, ekReplace, ekInsert, ekDelete

  EditOp* = object
    case kind*: EditKind
    of ekKeep, ekInsert, ekDelete:
      ch*: char
    of ekReplace:
      before*, after*: char

func keep*(c: char): EditOp {.raises: [].} = EditOp(kind: ekKeep, ch: c)
func insert*(c: char): EditOp {.raises: [].} = EditOp(kind: ekInsert, ch: c)
func delete*(c: char): EditOp {.raises: [].} = EditOp(kind: ekDelete, ch: c)
func replace*(before, after: char): EditOp {.raises: [].} =
  EditOp(kind: ekReplace, before: before, after: after)

func `==`*(x, y: EditOp): bool {.raises: [].} =
  if x.kind != y.kind: return false
  case x.kind
  of ekKeep, ekInsert, ekDelete: x.ch == y.ch
  of ekReplace: x.before == y.before and x.after == y.after

func cost*(op: EditOp): int {.raises: [].} =
  ## Keeping is free; every other operation costs one.
  case op.kind
  of ekKeep: 0
  of ekReplace, ekInsert, ekDelete: 1

func cost*(script: openArray[EditOp]): int {.raises: [].} =
  for op in script:
    result += op.cost

func editDistance*(a, b: string): int {.raises: [].} =
  ## Levenshtein distance (DP-EDIT-01 .. DP-EDIT-04).
  var prev = newSeq[int](b.len + 1)
  var cur = newSeq[int](b.len + 1)
  for j in 0 .. b.len:
    prev[j] = j
  for i in 1 .. a.len:
    cur[0] = i
    for j in 1 .. b.len:
      let sub = prev[j - 1] + (if a[i - 1] == b[j - 1]: 0 else: 1)
      cur[j] = min(sub, min(prev[j] + 1, cur[j - 1] + 1))
    swap(prev, cur)
  prev[b.len]

func editScript*(a, b: string): seq[EditOp] {.raises: [].} =
  ## A cheapest script from `a` to `b`. On ties the backtrack prefers keep/replace, then delete,
  ## then insert, so the result is deterministic (DP-EDIT-05).
  let w = b.len + 1
  var table = newSeq[int]((a.len + 1) * w)
  for j in 0 .. b.len:
    table[j] = j
  for i in 1 .. a.len:
    table[i * w] = i
    for j in 1 .. b.len:
      let sub = table[(i - 1) * w + j - 1] + (if a[i - 1] == b[j - 1]: 0 else: 1)
      table[i * w + j] = min(sub, min(table[(i - 1) * w + j] + 1, table[i * w + j - 1] + 1))
  var i = a.len
  var j = b.len
  var rev: seq[EditOp] = @[]
  while i > 0 or j > 0:
    if i > 0 and j > 0 and
        table[i * w + j] == table[(i - 1) * w + j - 1] + (if a[i - 1] == b[j - 1]: 0 else: 1):
      rev.add(if a[i - 1] == b[j - 1]: keep(a[i - 1]) else: replace(a[i - 1], b[j - 1]))
      dec i
      dec j
    elif i > 0 and table[i * w + j] == table[(i - 1) * w + j] + 1:
      rev.add delete(a[i - 1])
      dec i
    else:
      rev.add insert(b[j - 1])
      dec j
  result = newSeq[EditOp](rev.len)
  for k in 0 ..< rev.len:
    result[k] = rev[rev.len - 1 - k]

func applyScript*(a: string; script: openArray[EditOp]): Option[string] {.raises: [].} =
  ## Replays `script` on `a`. None when the script does not fit `a`: it names a character `a`
  ## does not have at that place, or leaves part of `a` unread (DP-EDIT-06).
  var at = 0
  var outStr = ""
  for op in script:
    case op.kind
    of ekKeep:
      if at >= a.len or a[at] != op.ch: return none(string)
      outStr.add op.ch
      inc at
    of ekReplace:
      if at >= a.len or a[at] != op.before: return none(string)
      outStr.add op.after
      inc at
    of ekDelete:
      if at >= a.len or a[at] != op.ch: return none(string)
      inc at
    of ekInsert:
      outStr.add op.ch
  if at != a.len: none(string) else: some(outStr)
```

```nim
## Fast Fibonacci by raising the matrix `[[1, 1], [1, 0]]` to the n-th power: its entries are
## F(n+1), F(n), F(n), F(n-1), and repeated squaring needs O(log n) multiplications.
##
## `fibMatrix` is exact and returns none beyond F(92), the last value that fits a signed 64-bit
## `int`; `fibMod` works modulo a validated modulus and accepts any n up to `high(int)`. Use the
## matrix form when n is huge and only a residue is needed, or as the first example of "a linear
## recurrence is a matrix power"; for small n a loop (`memoization.fibTable`) is simpler.

import std/options

type Mat = object
  a, b, c, d: uint64   # [[a, b], [c, d]]

const
  maxFibExact*: int = 92
    ## F(93) overflows a signed 64-bit integer.
  maxFibModulus*: int = 3_037_000_499
    ## Largest modulus whose residue products fit an `int`.

func mul(x, y: Mat): Mat {.raises: [].} =
  Mat(a: x.a * y.a + x.b * y.c, b: x.a * y.b + x.b * y.d,
      c: x.c * y.a + x.d * y.c, d: x.c * y.b + x.d * y.d)

func fibMatrix*(n: int): Option[int] {.raises: [].} =
  ## F(n) for 0 <= n <= `maxFibExact`, else none (NUM-FIBM-01, NUM-FIBM-03).
  ##
  ## Unsigned arithmetic wraps silently, so overflow is ruled out by bound: no power of the matrix
  ## beyond M^n is formed (the base is squared only while bits remain), and every entry of M^n is at
  ## most F(n+1) <= F(93) < 2^64.
  if n < 0 or n > maxFibExact:
    return none(int)
  var acc = Mat(a: 1, b: 0, c: 0, d: 1)
  var base = Mat(a: 1, b: 1, c: 1, d: 0)
  var e = n
  while e > 0:
    if (e and 1) == 1:
      acc = mul(acc, base)
    e = e shr 1
    if e > 0:
      base = mul(base, base)
  some(int(acc.b))

func fibMod*(n, m: int): Option[int] {.raises: [].} =
  ## F(n) mod m for n >= 0 and 1 <= m <= `maxFibModulus`, else none (NUM-FIBM-02, NUM-FIBM-04).
  if n < 0 or m < 1 or m > maxFibModulus:
    return none(int)
  func mulM(x, y: (int, int, int, int); m: int): (int, int, int, int) {.raises: [].} =
    ((x[0] * y[0] mod m + x[1] * y[2] mod m) mod m, (x[0] * y[1] mod m + x[1] * y[3] mod m) mod m,
     (x[2] * y[0] mod m + x[3] * y[2] mod m) mod m, (x[2] * y[1] mod m + x[3] * y[3] mod m) mod m)
  var acc = (1 mod m, 0, 0, 1 mod m)
  var base = (1 mod m, 1 mod m, 1 mod m, 0)
  var e = n
  while e > 0:
    if (e and 1) == 1:
      acc = mulM(acc, base, m)
    e = e shr 1
    if e > 0:
      base = mulM(base, base, m)
  some(acc[1])
```

```nim
## Floyd-Warshall: shortest paths between every pair, by allowing one more intermediate vertex at a time.
##
## Use it when you need distances between all pairs on a small dense graph (V up to a few hundred):
## O(V^3) time, O(V^2) space. Negative weights are fine; a negative cycle is reported as an error.
## For one source on a sparse graph, `dijkstra` or `bellman_ford` is cheaper. Distances are `int`.

import std/options
import nimcs/fp/result
import nimcs/algo/graph

type
  AllPairs* = object
    n: int
    dist: seq[Option[int]]    ## row-major n x n
    firstHop: seq[int]        ## row-major n x n: the vertex after u on a shortest u -> v path

  FloydError* = object
    ## The graph has a negative cycle; `vertex` lies on one.
    vertex*: int

func distance*(ap: AllPairs; u, v: int): Option[int] {.raises: [].} =
  ## Length of a shortest path u -> v, none when v is unreachable from u or either is not a vertex.
  if u < 0 or u >= ap.n or v < 0 or v >= ap.n: none(int) else: ap.dist[u * ap.n + v]

func pathBetween*(ap: AllPairs; u, v: int): Option[seq[int]] {.raises: [].} =
  ## The vertices of a shortest path u -> v, both ends included; none when unreachable
  ## (GRAPH-FLOYD-03).
  if ap.distance(u, v).isNone:
    return none(seq[int])
  var path = @[u]
  var current = u
  while current != v:
    current = ap.firstHop[current * ap.n + v]
    path.add current
    if path.len > ap.n:
      return none(seq[int])
  some(path)

func floydWarshall*(g: Graph): Result[AllPairs, FloydError] {.raises: [].} =
  ## All-pairs shortest distances (GRAPH-FLOYD-01), or a negative cycle (GRAPH-FLOYD-02).
  let n = g.vertexCount
  var dist = newSeq[Option[int]](n * n)
  var hop = newSeq[int](n * n)
  for v in 0 ..< n:
    dist[v * n + v] = some(0)
    hop[v * n + v] = v
  for u in 0 ..< n:
    for a in g.neighbors(u):
      let at = u * n + a.target
      if dist[at].isNone or a.weight < dist[at].get:
        dist[at] = some(a.weight)
        hop[at] = a.target
  for k in 0 ..< n:
    for i in 0 ..< n:
      let ik = dist[i * n + k]
      if ik.isNone: continue
      for j in 0 ..< n:
        let kj = dist[k * n + j]
        if kj.isNone: continue
        let through = ik.get + kj.get
        if dist[i * n + j].isNone or through < dist[i * n + j].get:
          dist[i * n + j] = some(through)
          hop[i * n + j] = hop[i * n + k]
    # A negative diagonal entry is a negative cycle; stopping here keeps the values from
    # doubling pass after pass on a graph that has one.
    for v in 0 ..< n:
      if dist[v * n + v].get < 0:
        return err(AllPairs, FloydError(vertex: v))
  ok(AllPairs(n: n, dist: dist, firstHop: hop), FloydError)
```

```nim
## An immutable graph value: vertices 0 ..< n and adjacency lists built from an edge list.
##
## Use it as the input of every graph algorithm in this package (`bfs`, `dfs`, `dijkstra`, ...).
## `buildGraph` is the only way to make one: it checks the edges and puts each neighbour list in
## ascending (target, weight) order, so the same set of edges gives equal graphs whatever order
## it arrived in, and every algorithm that visits neighbours in order is deterministic. An
## undirected edge is stored as two arcs (one for a self-loop). Parallel edges are kept.
## This module also holds the result types the algorithms share: `PathTree` and `SpanningForest`.

import std/[algorithm, options]
import nimcs/fp/result

type
  GraphKind* = enum
    gkDirected     ## an edge u -> v can be followed from u only
    gkUndirected   ## an edge u - v can be followed both ways

  GraphError* = enum
    geNegativeOrder      ## the vertex count is below zero
    geVertexOutOfRange   ## an endpoint (or a source) is not in 0 ..< n
    geNegativeWeight     ## the algorithm needs non-negative weights
    geNotUndirected      ## the algorithm is defined for undirected graphs only

  Edge* = object
    source*, target*, weight*: int

  Arc* = object
    ## One direction of an edge, as stored in a neighbour list.
    target*, weight*: int

  Graph* = object
    directed: bool
    adj: seq[seq[Arc]]

  PathTree* = object
    ## Shortest paths from one source: distance and predecessor of every vertex (none = unreached).
    source*: int
    dist*: seq[Option[int]]
    parent*: seq[Option[int]]

  SpanningForest* = object
    ## A minimum spanning tree of every connected component.
    edges*: seq[Edge]     ## in ascending (weight, source, target) order, source <= target
    totalWeight*: int
    components*: int

func `==`*(a, b: Edge): bool {.raises: [].} =
  a.source == b.source and a.target == b.target and a.weight == b.weight

func `==`*(a, b: Arc): bool {.raises: [].} =
  a.target == b.target and a.weight == b.weight

func `==`*(a, b: Graph): bool {.raises: [].} =
  a.directed == b.directed and a.adj == b.adj

func `==`*(a, b: PathTree): bool {.raises: [].} =
  a.source == b.source and a.dist == b.dist and a.parent == b.parent

func edge*(source, target: int; weight = 1): Edge {.raises: [].} =
  Edge(source: source, target: target, weight: weight)

func arcOrder(a, b: Arc): int =
  result = cmp(a.target, b.target)
  if result == 0:
    result = cmp(a.weight, b.weight)

func buildGraph*(order: int; edges: openArray[Edge]; kind: GraphKind): Result[Graph, GraphError] {.raises: [].} =
  ## A graph on vertices 0 ..< order. Fails when `order` is negative or an endpoint is outside
  ## that range (GRAPH-BUILD-02).
  if order < 0:
    return err(Graph, geNegativeOrder)
  var adj = newSeq[seq[Arc]](order)
  for e in edges:
    if e.source < 0 or e.source >= order or e.target < 0 or e.target >= order:
      return err(Graph, geVertexOutOfRange)
    adj[e.source].add Arc(target: e.target, weight: e.weight)
    if kind == gkUndirected and e.source != e.target:
      adj[e.target].add Arc(target: e.source, weight: e.weight)
  for v in 0 ..< order:
    adj[v] = sorted(adj[v], arcOrder)
  ok(Graph(directed: kind == gkDirected, adj: adj), GraphError)

func vertexCount*(g: Graph): int {.raises: [].} = g.adj.len

func isDirected*(g: Graph): bool {.raises: [].} = g.directed

func neighbors*(g: Graph; v: int): lent seq[Arc] {.raises: [].} =
  ## The arcs leaving `v`, ascending by (target, weight). `v` must be in 0 ..< vertexCount; an
  ## outside vertex is a caller bug and raises an `IndexDefect` (a Defect, not a failure value).
  g.adj[v]

func inRange*(g: Graph; v: int): bool {.raises: [].} = v >= 0 and v < g.adj.len

func arcCount*(g: Graph): int {.raises: [].} =
  for list in g.adj:
    result += list.len

func hasArc*(g: Graph; u, v: int): bool {.raises: [].} =
  ## Is there an arc u -> v? (Always symmetric for an undirected graph.)
  if not g.inRange(u) or not g.inRange(v):
    return false
  for a in g.adj[u]:
    if a.target == v:
      return true
  false

func edges*(g: Graph): seq[Edge] {.raises: [].} =
  ## Every edge once, in ascending (source, target, weight) order. For an undirected graph each
  ## edge is reported with source <= target (GRAPH-BUILD-03).
  for u in 0 ..< g.adj.len:
    for a in g.adj[u]:
      if g.directed or u <= a.target:
        result.add Edge(source: u, target: a.target, weight: a.weight)

func transpose*(g: Graph): Graph {.raises: [].} =
  ## Every arc reversed. An undirected graph is its own transpose (GRAPH-TRANSPOSE-01).
  if not g.directed:
    return g
  var adj = newSeq[seq[Arc]](g.adj.len)
  for u in 0 ..< g.adj.len:
    for a in g.adj[u]:
      adj[a.target].add Arc(target: u, weight: a.weight)
  for v in 0 ..< adj.len:
    adj[v] = sorted(adj[v], arcOrder)
  Graph(directed: true, adj: adj)

func distance*(t: PathTree; v: int): Option[int] {.raises: [].} =
  ## Length of a shortest path from the source to `v`; none when `v` is unreachable or not a vertex.
  if v < 0 or v >= t.dist.len: none(int) else: t.dist[v]

func pathTo*(t: PathTree; v: int): Option[seq[int]] {.raises: [].} =
  ## The vertices of a shortest path from the source to `v`, both ends included; none when
  ## `v` is unreachable (GRAPH-PATH-01).
  if v < 0 or v >= t.dist.len or t.dist[v].isNone:
    return none(seq[int])
  var path = @[v]
  var current = v
  while current != t.source:
    let p = t.parent[current]
    if p.isNone or path.len > t.dist.len:
      return none(seq[int])
    current = p.get
    path.add current
  path.reverse
  some(path)
```

```nim
## Knuth–Morris–Pratt substring search: never move backwards in the text.
##
## The failure table says, for each prefix of the pattern, how long its longest proper border is
## (a prefix that is also a suffix). After a mismatch the search resumes from that border instead of
## from scratch, so the work is linear in `text.len + pattern.len`. Use it for one pattern over
## streaming or adversarial text; `z_algorithm` gives the same answers by another route, and
## `rabin_karp` is the choice for many patterns of one length.
##
## Positions are 0-based start offsets of every occurrence, overlapping ones included. An empty
## pattern occurs at every offset 0 .. text.len (STR-KMP-04).

func kmpFailure*(pattern: string): seq[int] {.raises: [].} =
  ## `result[i]` is the length of the longest proper border of `pattern[0 .. i]` (STR-KMP-01).
  result = newSeq[int](pattern.len)
  var k = 0
  for i in 1 ..< pattern.len:
    while k > 0 and pattern[i] != pattern[k]:
      k = result[k - 1]
    if pattern[i] == pattern[k]:
      inc k
    result[i] = k

func kmpFindAll*(text, pattern: string): seq[int] {.raises: [].} =
  ## Start offsets of all occurrences of `pattern` in `text`, ascending (STR-KMP-02, STR-KMP-03).
  result = @[]
  if pattern.len == 0:
    for i in 0 .. text.len:
      result.add i
    return
  let fail = kmpFailure(pattern)
  var k = 0
  for i in 0 ..< text.len:
    while k > 0 and text[i] != pattern[k]:
      k = fail[k - 1]
    if text[i] == pattern[k]:
      inc k
    if k == pattern.len:
      result.add i - pattern.len + 1
      k = fail[k - 1]
```

```nim
## Kruskal's algorithm: take the cheapest edges first, skipping any that would close a cycle.
##
## Use it to connect all vertices of an undirected weighted graph at least total cost (cabling,
## clustering). Sorting the edges dominates: O(E log E); a union-find forest (union by size and
## path halving: inverse-Ackermann amortized) tells in near-constant time whether two vertices are already joined. On a disconnected graph the result is a spanning
## forest, one tree per component. A directed graph is refused. `prim` gives the same total weight.

import std/algorithm
import nimcs/fp/result
import nimcs/algo/graph

func root(parent: var seq[int]; x: int): int {.raises: [].} =
  ## Representative of x's set; halves the path as it climbs.
  var current = x
  while parent[current] != current:
    parent[current] = parent[parent[current]]
    current = parent[current]
  current

func byWeight(a, b: Edge): int =
  result = cmp(a.weight, b.weight)
  if result == 0:
    result = cmp(a.source, b.source)
  if result == 0:
    result = cmp(a.target, b.target)

func kruskal*(g: Graph): Result[SpanningForest, GraphError] {.raises: [].} =
  ## A minimum spanning forest (GRAPH-KRUSKAL-01). Fails with `geNotUndirected` for a directed graph.
  if g.isDirected:
    return err(SpanningForest, geNotUndirected)
  let n = g.vertexCount
  var parent = newSeq[int](n)
  var size = newSeq[int](n)
  for v in 0 ..< n:
    parent[v] = v
    size[v] = 1
  var forest = SpanningForest(components: n)
  for e in sorted(g.edges, byWeight):
    let a = root(parent, e.source)
    let b = root(parent, e.target)
    if a != b:
      let (big, small) = if size[a] >= size[b]: (a, b) else: (b, a)
      parent[small] = big          # the smaller tree hangs under the larger: depth stays O(log n)
      size[big] += size[small]
      forest.edges.add e
      forest.totalWeight += e.weight
      dec forest.components
  ok(forest, GraphError)
```

```nim
## Longest common subsequence: the longest sequence that can be obtained from both inputs by
## deleting elements (not necessarily contiguous ones).
##
## Use it to compare two sequences when order matters but gaps are allowed (diff tools, DNA
## similarity). The table is a local `var`; the public routines are pure. For contiguous
## matches use `kmp` or `suffix_array` instead.

func lcsLength*[T](a, b: openArray[T]): int {.raises: [].} =
  ## Length of a longest common subsequence (DP-LCS-01, DP-LCS-03).
  var prev = newSeq[int](b.len + 1)
  var cur = newSeq[int](b.len + 1)
  for i in 1 .. a.len:
    for j in 1 .. b.len:
      cur[j] =
        if a[i - 1] == b[j - 1]: prev[j - 1] + 1
        else: max(prev[j], cur[j - 1])
    swap(prev, cur)
  prev[b.len]

func lcs*[T](a, b: openArray[T]): seq[T] {.raises: [].} =
  ## One longest common subsequence. Among the longest ones it is the one the backtrack from the
  ## bottom-right corner finds, preferring to move up on a tie (deterministic, DP-LCS-05).
  let w = b.len + 1
  var table = newSeq[int]((a.len + 1) * w)
  for i in 1 .. a.len:
    for j in 1 .. b.len:
      table[i * w + j] =
        if a[i - 1] == b[j - 1]: table[(i - 1) * w + j - 1] + 1
        else: max(table[(i - 1) * w + j], table[i * w + j - 1])
  var i = a.len
  var j = b.len
  var rev: seq[T] = @[]
  while i > 0 and j > 0:
    if a[i - 1] == b[j - 1]:
      rev.add a[i - 1]
      dec i
      dec j
    elif table[(i - 1) * w + j] >= table[i * w + j - 1]:
      dec i
    else:
      dec j
  result = newSeq[T](rev.len)
  for k in 0 ..< rev.len:
    result[k] = rev[rev.len - 1 - k]

func lcs*(a, b: string): string {.raises: [].} =
  ## The string form of `lcs`.
  var chars: seq[char] = @[]
  for c in lcs(a.toOpenArray(0, a.high), b.toOpenArray(0, b.high)):
    chars.add c
  result = newString(chars.len)
  for k in 0 ..< chars.len:
    result[k] = chars[k]

func isSubsequence*[T](small, big: openArray[T]): bool {.raises: [].} =
  ## True when `small` can be read off `big` left to right with gaps (DP-LCS-02).
  var at = 0
  for x in big:
    if at < small.len and small[at] == x:
      inc at
  at == small.len
```

```nim
## Memoization without hidden state: the table of already computed answers is a value that is
## passed in and handed back, so a call can be repeated, replayed or shared between callers.
##
## Use it when a recursive definition recomputes the same sub-problems (Fibonacci, paths in a
## grid). The top-down form (`fibMemo`, `gridPathsMemo`) threads a `Memo` through the recursion;
## the bottom-up form (`fibTable`, `gridPathsTable`) fills a local table in dependency order.
## Both give the same answers (DP-MEMO-02, DP-MEMO-05). Neither uses a global cache, so a
## function that looks "memoized" from the outside is still a pure function of its arguments.

import std/[options, tables]

type
  Memo*[K, V] = object
    ## Answers already known, keyed by the sub-problem. Never mutated in place by a caller:
    ## `put` returns a new memo.
    cells: Table[K, V]

  FibResult* = object
    ## The answer and the memo to pass to the next call.
    value*: int
    memo*: Memo[int, int]

  GridResult* = object
    paths*: int
    memo*: Memo[(int, int), int]

const
  maxFib* = 92
    ## `fib(93)` does not fit a signed 64-bit integer.
  maxGridSteps* = 64
    ## `rows + cols` up to this bound keeps the path count below `high(int)`.

func initMemo*[K, V](): Memo[K, V] {.raises: [].} =
  Memo[K, V](cells: initTable[K, V]())

func get*[K, V](m: Memo[K, V]; key: K): Option[V] {.raises: [].} =
  ## The stored answer, or none (DP-MEMO-03).
  if m.cells.hasKey(key): some(m.cells.getOrDefault(key)) else: none(V)

func put*[K, V](m: Memo[K, V]; key: K; value: V): Memo[K, V] {.raises: [].} =
  ## A memo that also knows `key`; `m` itself is unchanged (DP-MEMO-03).
  result = m
  result.cells[key] = value

func len*[K, V](m: Memo[K, V]): int {.raises: [].} =
  m.cells.len

func fibStep(n: int; memo: Memo[int, int]): FibResult {.raises: [].} =
  if n < 2:
    return FibResult(value: n, memo: memo)
  let known = memo.get(n)
  if known.isSome:
    return FibResult(value: known.get, memo: memo)
  let a = fibStep(n - 1, memo)
  let b = fibStep(n - 2, a.memo)
  let total = a.value + b.value
  FibResult(value: total, memo: b.memo.put(n, total))

func fibMemo*(n: int; memo: Memo[int, int]): Option[FibResult] {.raises: [].} =
  ## Fibonacci, top-down, threading `memo`. None unless 0 <= n <= `maxFib` (DP-MEMO-04).
  if n < 0 or n > maxFib: none(FibResult)
  else: some(fibStep(n, memo))

func fibTable*(n: int): Option[int] {.raises: [].} =
  ## Fibonacci, bottom-up with two rolling values. None unless 0 <= n <= `maxFib`.
  if n < 0 or n > maxFib:
    return none(int)
  if n == 0:
    return some(0)
  var prev = 0
  var cur = 1
  for _ in 1 ..< n:
    let next = prev + cur
    prev = cur
    cur = next
  some(cur)

func gridStep(r, c: int; memo: Memo[(int, int), int]): GridResult {.raises: [].} =
  if r == 0 or c == 0:
    return GridResult(paths: 1, memo: memo)
  let known = memo.get((r, c))
  if known.isSome:
    return GridResult(paths: known.get, memo: memo)
  let a = gridStep(r - 1, c, memo)
  let b = gridStep(r, c - 1, a.memo)
  let total = a.paths + b.paths
  GridResult(paths: total, memo: b.memo.put((r, c), total))

func gridPathsMemo*(rows, cols: int; memo: Memo[(int, int), int]): Option[GridResult] {.raises: [].} =
  ## Number of right/down paths from the top-left to the bottom-right cell of a `rows` x `cols`
  ## grid, top-down. None unless both are >= 1 and `rows + cols` <= `maxGridSteps`.
  if rows < 1 or cols < 1 or rows + cols > maxGridSteps: none(GridResult)
  else: some(gridStep(rows - 1, cols - 1, memo))

func gridPathsTable*(rows, cols: int): Option[int] {.raises: [].} =
  ## The same count, bottom-up with one rolling row.
  if rows < 1 or cols < 1 or rows + cols > maxGridSteps:
    return none(int)
  var row = newSeq[int](cols)
  for j in 0 ..< cols:
    row[j] = 1
  for _ in 1 ..< rows:
    for j in 1 ..< cols:
      row[j] += row[j - 1]
  some(row[cols - 1])
```

```nim
## Integer number theory: greatest common divisor, Bezout coefficients, modular exponentiation
## and modular inverses.
##
## Every routine that can fail says so in its type. `gcd`, `lcm` and `extGcd` return `Option`
## because `abs(low(int))` and some products are not representable; `powMod` and `modInverse`
## take a `Modulus`, a distinct type built by `modulus`, so a zero or negative modulus cannot reach
## them. The largest modulus is chosen so that the product of two residues fits an `int`
## (see `maxModulus`). Use these as the building blocks for RSA-style toy examples, hashing
## and the Chinese remainder theorem; for large moduli use a big-integer library.

import std/options

type
  Modulus* = distinct int
  Bezout* = object
    ## `a * x + b * y == g` with `g` the (non-negative) gcd.
    g*, x*, y*: int

const maxModulus*: int = 3_037_000_499
  ## floor(sqrt(2^63 - 1)): `(m - 1) * (m - 1)` still fits a 64-bit `int`.

func modulus*(m: int): Option[Modulus] {.raises: [].} =
  ## A modulus lies in 1 .. `maxModulus` (NUM-NT-06).
  if m < 1 or m > maxModulus: none(Modulus) else: some(Modulus(m))

func `==`*(a, b: Modulus): bool {.borrow.}
func `$`*(m: Modulus): string {.borrow.}

func toInt*(m: Modulus): int {.raises: [].} = int(m)

func residue*(a: int; m: Modulus): int {.raises: [].} =
  ## `a` reduced into 0 ..< m, also for negative `a`.
  let mi = int(m)
  ((a mod mi) + mi) mod mi

func gcd*(a, b: int): Option[int] {.raises: [].} =
  ## Greatest common divisor, never negative; `gcd(0, 0)` is 0. None when an argument is
  ## `low(int)`, whose magnitude does not fit (NUM-NT-01).
  if a == low(int) or b == low(int):
    return none(int)
  var x = abs(a)
  var y = abs(b)
  while y != 0:
    (x, y) = (y, x mod y)
  some(x)

func lcm*(a, b: int): Option[int] {.raises: [].} =
  ## Least common multiple, never negative; zero if either argument is zero. None on overflow
  ## or `low(int)` (NUM-NT-02).
  let g = gcd(a, b)
  if g.isNone:
    return none(int)
  if a == 0 or b == 0:
    return some(0)
  let q = abs(a) div g.get
  let m = abs(b)
  if q > high(int) div m: none(int) else: some(q * m)

func extGcd*(a, b: int): Option[Bezout] {.raises: [].} =
  ## The gcd with Bezout coefficients: `a * x + b * y == g` (NUM-NT-03). None when an argument is
  ## `low(int)`.
  if a == low(int) or b == low(int):
    return none(Bezout)
  var oldR = abs(a)
  var r = abs(b)
  var oldS = 1
  var s = 0
  var oldT = 0
  var t = 1
  while r != 0:
    let q = oldR div r
    (oldR, r) = (r, oldR - q * r)
    (oldS, s) = (s, oldS - q * s)
    (oldT, t) = (t, oldT - q * t)
  some(Bezout(g: oldR, x: (if a < 0: -oldS else: oldS), y: (if b < 0: -oldT else: oldT)))

func powMod*(base, exp: int; m: Modulus): Option[int] {.raises: [].} =
  ## `base ^ exp mod m` by repeated squaring, in 0 ..< m. None for a negative exponent
  ## (NUM-NT-04). `powMod(x, 0, m)` is 1 mod m, so 0 when `m` is 1.
  if exp < 0:
    return none(int)
  let mi = int(m)
  var acc = 1 mod mi
  var b = residue(base, m)
  var e = exp
  while e > 0:
    if (e and 1) == 1:
      acc = acc * b mod mi
    e = e shr 1
    if e > 0:
      b = b * b mod mi
  some(acc)

func modInverse*(a: int; m: Modulus): Option[int] {.raises: [].} =
  ## The `x` in 0 ..< m with `a * x ≡ 1 (mod m)`, or none when `a` and `m` are not coprime
  ## (NUM-NT-05).
  let r = extGcd(residue(a, m), int(m))
  if r.isNone or r.get.g != 1:
    return none(int)
  some(residue(r.get.x, m))
```

```nim
## Prim's algorithm: grow one tree from a start vertex, always adding the cheapest edge that leaves it.
##
## Use it for the same job as `kruskal` (minimum spanning tree of an undirected weighted graph),
## typically when the graph is dense or given as adjacency lists. A binary heap of candidate edges
## gives O(E log V). When the graph is disconnected a new tree is started from the smallest
## unvisited vertex, so the result is a spanning forest. A directed graph is refused.

import std/[algorithm, heapqueue]
import nimcs/fp/result
import nimcs/algo/graph

func byWeight(a, b: Edge): int =
  result = cmp(a.weight, b.weight)
  if result == 0:
    result = cmp(a.source, b.source)
  if result == 0:
    result = cmp(a.target, b.target)

func prim*(g: Graph): Result[SpanningForest, GraphError] {.raises: [].} =
  ## A minimum spanning forest (GRAPH-PRIM-01). Fails with `geNotUndirected` for a directed graph.
  if g.isDirected:
    return err(SpanningForest, geNotUndirected)
  let n = g.vertexCount
  var inTree = newSeq[bool](n)
  var forest = SpanningForest()
  for start in 0 ..< n:
    if inTree[start]: continue
    inc forest.components
    inTree[start] = true
    var candidates = initHeapQueue[(int, int, int)]()    # (weight, from, to)
    for a in g.neighbors(start):
      candidates.push (a.weight, start, a.target)
    while candidates.len > 0:
      let (w, u, v) = candidates.pop
      if inTree[v]: continue
      inTree[v] = true
      forest.edges.add edge(min(u, v), max(u, v), w)
      forest.totalWeight += w
      for a in g.neighbors(v):
        if not inTree[a.target]:
          candidates.push (a.weight, v, a.target)
  forest.edges = sorted(forest.edges, byWeight)
  ok(forest, GraphError)
```

```nim
## Rabin–Karp search: slide a window over the text, keeping a polynomial hash of the window
## that is updated in O(1) when the window moves, and compare characters only where the hash of
## the window equals the hash of the pattern.
##
## The modulus is explicit and validated (`HashModulus` is a distinct type built by `hashModulus`; the name differs from `number_theory.Modulus` so both modules can be imported together). A hash
## match is only a candidate: every candidate is verified against the text, so the result never
## contains a false positive whatever the modulus (STR-RK-03); a small modulus only makes the
## search slower, never wrong. Use it for many same-length patterns (hash them once) or when a
## rolling fingerprint is wanted; for one pattern with guaranteed linear time use `kmp`.

import std/options

type
  HashModulus* = distinct int
  HashParams* = object
    base*: int
    modulus*: HashModulus

const maxHashModulus*: int = 2_147_483_647
  ## 2^31 - 1: `hash * base + c` stays below 2^62, so no step overflows a 64-bit `int`.

func hashModulus*(m: int): Option[HashModulus] {.raises: [].} =
  ## A modulus must lie in 2 .. `maxHashModulus` (STR-RK-05).
  if m < 2 or m > maxHashModulus: none(HashModulus) else: some(HashModulus(m))

func `==`*(a, b: HashModulus): bool {.borrow.}
func `$`*(m: HashModulus): string {.borrow.}

func hashModulusValue*(m: HashModulus): int {.raises: [].} = int(m)

func params*(base: int; m: HashModulus): Option[HashParams] {.raises: [].} =
  ## The base must be at least 2 and below the modulus (STR-RK-05).
  if base < 2 or base >= int(m): none(HashParams)
  else: some(HashParams(base: base, modulus: m))

func hashOf*(s: openArray[char]; p: HashParams): int {.raises: [].} =
  ## Polynomial hash of `s` (STR-RK-01).
  let m = int(p.modulus)
  for c in s:
    result = (result * p.base + ord(c)) mod m

func rollingHashes*(text: string; width: int; p: HashParams): seq[int] {.raises: [].} =
  ## The hash of every window `text[i ..< i + width]`, each obtained from the previous one in
  ## O(1) (STR-RK-01). Empty when `width` < 1 or larger than the text.
  result = @[]
  if width < 1 or width > text.len:
    return
  let m = int(p.modulus)
  var lead = 1                      # base^(width-1) mod m
  for _ in 1 ..< width:
    lead = lead * p.base mod m
  var h = hashOf(text.toOpenArray(0, width - 1), p)
  result.add h
  for i in width ..< text.len:
    let drop = ord(text[i - width]) * lead mod m
    h = ((h - drop + m) mod m * p.base + ord(text[i])) mod m
    result.add h

func rkFindAll*(text, pattern: string; p: HashParams): seq[int] {.raises: [].} =
  ## Start offsets of all occurrences of `pattern`, ascending; every hash candidate is verified
  ## (STR-RK-02, STR-RK-03). An empty pattern occurs at every offset 0 .. text.len (STR-RK-04).
  result = @[]
  let w = pattern.len
  if w == 0:
    for i in 0 .. text.len:
      result.add i
    return
  if w > text.len:
    return
  let target = hashOf(pattern, p)
  let hashes = rollingHashes(text, w, p)
  for i in 0 ..< hashes.len:
    if hashes[i] == target:
      var same = true
      for j in 0 ..< w:
        if text[i + j] != pattern[j]:
          same = false
          break
      if same:
        result.add i

func rkCandidates*(text, pattern: string; p: HashParams): seq[int] {.raises: [].} =
  ## Offsets whose window hash equals the pattern hash, before verification. A superset of
  ## `rkFindAll` (STR-RK-03); exposed so a test can show that collisions are filtered out.
  result = @[]
  let w = pattern.len
  if w == 0 or w > text.len:
    return
  let target = hashOf(pattern, p)
  let hashes = rollingHashes(text, w, p)
  for i in 0 ..< hashes.len:
    if hashes[i] == target:
      result.add i
```

```nim
## Radix sort and counting sort: sort by integer keys without comparing elements.
##
## Use them when keys are non-negative integers (or map to a small range): counting sort is
## O(n + k) for keys below k; LSD radix sort (least significant byte first, one stable counting
## pass per byte) is O(n * bytes). Both are stable and report bad keys as a `Result` error
## instead of guessing. Prefer a comparison sort for arbitrary keys. Inputs are never changed.

import nimcs/fp/result

const maxCountingBound* = 1 shl 24
  ## Largest `bound` that counting sort accepts: it allocates one counter per key value, so a
  ## caller-chosen bound would otherwise decide how much memory the routine takes.

type SortKeyError* = enum
  skNegative    ## a key below zero
  skOutOfRange  ## a key at or above the stated bound
  skBadBound    ## the bound is not positive
  skBoundTooLarge  ## the bound exceeds `maxCountingBound`

func countingSortBy*[T](xs: openArray[T]; bound: int;
    key: proc(x: T): int {.noSideEffect, raises: [].}): Result[seq[T], SortKeyError] {.raises: [].} =
  ## Stable sort by `key(x)`, which must lie in 0 ..< bound (SORT-RADIX-03, SORT-RADIX-04);
  ## a bound above `maxCountingBound` is refused (SORT-RADIX-06).
  if bound < 1:
    return err(seq[T], skBadBound)
  if bound > maxCountingBound:
    return err(seq[T], skBoundTooLarge)
  var counts = newSeq[int](bound + 1)
  for x in xs:
    let k = key(x)
    if k < 0:
      return err(seq[T], skNegative)
    if k >= bound:
      return err(seq[T], skOutOfRange)
    inc counts[k + 1]
  for k in 1 .. bound:
    counts[k] += counts[k - 1]            # counts[k] = number of elements with a smaller key
  var placed = newSeq[T](xs.len)
  for x in xs:
    let k = key(x)
    placed[counts[k]] = x
    inc counts[k]
  ok(placed, SortKeyError)

func countingSort*(xs: openArray[int]; bound: int): Result[seq[int], SortKeyError] {.raises: [].} =
  ## Sorts integers that lie in 0 ..< bound.
  countingSortBy(xs, bound, proc(x: int): int {.noSideEffect, raises: [].} = x)

func radixSort*(xs: openArray[int]): Result[seq[int], SortKeyError] {.raises: [].} =
  ## LSD radix sort, base 256, for non-negative integers (SORT-RADIX-01, SORT-RADIX-02).
  var biggest = 0
  for x in xs:
    if x < 0:
      return err(seq[int], skNegative)
    biggest = max(biggest, x)
  var current = @xs
  var shift = 0
  while shift < 63 and (biggest shr shift) > 0:
    var counts: array[257, int]
    for x in current:
      inc counts[((x shr shift) and 255) + 1]
    for d in 1 .. 256:
      counts[d] += counts[d - 1]
    var next = newSeq[int](current.len)
    for x in current:
      let d = (x shr shift) and 255
      next[counts[d]] = x
      inc counts[d]
    current = next
    shift += 8
  ok(current, SortKeyError)
```

```nim
## Sieve of Eratosthenes: all primes up to a limit by crossing off the multiples of each prime.
##
## Use it when many primality answers are needed below a known bound: O(n log log n) time and
## O(n) space for every prime up to n, against O(sqrt n) per query for trial division
## (`isPrimeTrial`). For a single huge number use a probabilistic test instead of either.
## A limit below 2 has no primes, so the answer is simply empty.

import std/options

const maxSieveLimit*: int = 100_000_000
  ## Largest limit accepted; the flag table has `limit + 1` bytes.

func sieveFlags*(limit: int): Option[seq[bool]] {.raises: [].} =
  ## `result[i]` is true exactly when `i` is prime, for 0 <= i <= limit (NUM-SIEVE-01). The table is
  ## empty when `limit` is negative; none when `limit` exceeds `maxSieveLimit` (NUM-SIEVE-04).
  if limit > maxSieveLimit:
    return none(seq[bool])
  if limit < 0:
    return some(newSeq[bool]())
  var flags = newSeq[bool](limit + 1)
  for i in 2 .. limit:
    flags[i] = true
  var p = 2
  while p <= limit div p:
    if flags[p]:
      var multiple = p * p
      while multiple <= limit:
        flags[multiple] = false
        multiple += p
    inc p
  some(flags)

func primesUpTo*(limit: int): Option[seq[int]] {.raises: [].} =
  ## All primes <= `limit`, ascending (NUM-SIEVE-02, NUM-SIEVE-03); none beyond `maxSieveLimit`.
  let flags = sieveFlags(limit)
  if flags.isNone:
    return none(seq[int])
  var primes: seq[int] = @[]
  for i in 0 ..< flags.get.len:
    if flags.get[i]:
      primes.add i
  some(primes)

func isPrimeTrial*(n: int): bool {.raises: [].} =
  ## Primality by trial division up to the square root; the reference the sieve is checked
  ## against (NUM-SIEVE-01).
  if n < 2:
    return false
  var d = 2
  while d <= n div d:
    if n mod d == 0:
      return false
    inc d
  true
```

```nim
## Suffix array by prefix doubling, and the LCP array by Kasai's method.
##
## The suffix array lists the start offsets of all suffixes of a string in sorted order. Prefix
## doubling ranks suffixes by their first 1, 2, 4, ... characters, sorting pairs of ranks until all
## ranks differ: O(n log^2 n) with a comparison sort. The LCP array stores, next to each suffix, the
## length of the prefix it shares with the previous suffix in sorted order; Kasai computes it in O(n)
## by never letting the shared length drop by more than one between neighbouring text positions.
##
## Use it for substring search by binary search, counting distinct substrings and longest
## repeated substring. For a single search `kmp` or `z_algorithm` is simpler; a suffix tree
## answers the same questions with a larger structure.

import std/[algorithm, options]

func suffixArray*(s: string): seq[int] {.raises: [].} =
  ## Offsets of the suffixes of `s` in ascending lexicographic order (STR-SA-01, STR-SA-02).
  let n = s.len
  result = newSeq[int](n)
  if n == 0:
    return
  var rank = newSeq[int](n)
  var next = newSeq[int](n)
  for i in 0 ..< n:
    result[i] = i
    rank[i] = ord(s[i])
  var k = 1
  while true:
    let width = k
    let ranks = rank
    func key(i: int): (int, int) {.raises: [].} =
      (ranks[i], if i + width < n: ranks[i + width] else: -1)
    result.sort(proc(a, b: int): int {.raises: [].} = cmp(key(a), key(b)))
    next[result[0]] = 0
    for i in 1 ..< n:
      next[result[i]] = next[result[i - 1]] + (if key(result[i - 1]) < key(result[i]): 1 else: 0)
    rank = next
    if rank[result[n - 1]] == n - 1:
      break
    k *= 2

func isSuffixArrayOf*(sa: openArray[int]; s: string): bool {.raises: [].} =
  ## True when `sa` is a permutation of 0 ..< s.len whose suffixes are strictly ascending
  ## (STR-SA-01). O(n): after the permutation check, the suffix at `sa[i-1]` is smaller than the
  ## one at `sa[i]` exactly when its first character is smaller, or the first characters are equal
  ## and the rest of the first suffix sits earlier in `sa` (an empty rest sits before everything).
  ## Used by `lcpArray` to reject a bad array, and by tests as the law.
  if sa.len != s.len:
    return false
  var rankOf = newSeq[int](s.len + 1)   # rankOf[s.len] = -1: the empty suffix
  rankOf[s.len] = -1
  var seen = newSeq[bool](s.len)
  for i, at in sa:
    if at < 0 or at >= s.len or seen[at]:
      return false
    seen[at] = true
    rankOf[at] = i
  for i in 1 ..< sa.len:
    let a = sa[i - 1]
    let b = sa[i]
    if s[a] > s[b] or (s[a] == s[b] and rankOf[a + 1] > rankOf[b + 1]):
      return false
  true

func lcpArray*(s: string; sa: openArray[int]): Option[seq[int]] {.raises: [].} =
  ## `result[i]` is the length of the longest common prefix of the suffixes at `sa[i - 1]` and
  ## `sa[i]`; `result[0]` is 0 (STR-SA-03). None when `sa` is not the suffix array of `s`
  ## (STR-SA-04).
  if not isSuffixArrayOf(sa, s):
    return none(seq[int])
  let n = s.len
  var rankOf = newSeq[int](n)
  for i in 0 ..< n:
    rankOf[sa[i]] = i
  var lcp = newSeq[int](n)
  var h = 0
  for i in 0 ..< n:
    if rankOf[i] > 0:
      let j = sa[rankOf[i] - 1]
      while i + h < n and j + h < n and s[i + h] == s[j + h]:
        inc h
      lcp[rankOf[i]] = h
      if h > 0:
        dec h
    else:
      h = 0
  some(lcp)

func countDistinctSubstrings*(s: string): int {.raises: [].} =
  ## Number of different non-empty substrings: all `n(n+1)/2` of them minus the repeated
  ## prefixes the LCP array counts (STR-SA-05).
  let n = s.len
  if n == 0:
    return 0
  let sa = suffixArray(s)
  let lcp = lcpArray(s, sa).get
  result = n * (n + 1) div 2
  for h in lcp:
    result -= h
```

```nim
## Topological sort (Kahn's algorithm): repeatedly take a vertex with no remaining incoming arc.
##
## Use it to order tasks, build steps or modules so that every dependency comes before what needs
## it. It runs in O((V + E) log V) because the ready vertices sit in a small priority queue; that
## makes the answer the lexicographically smallest valid order, which is deterministic. A cycle has
## no valid order: the error carries one cycle, so the caller can report it.

import std/heapqueue
import nimcs/fp/result
import nimcs/algo/graph

type TopoCycle* = object
  ## A directed cycle v0 -> v1 -> ... -> vk -> v0, listed once around (no repeated first vertex), starting at its smallest vertex.
  vertices*: seq[int]

func findCycle(g: Graph; removed: seq[bool]): seq[int] {.raises: [].} =
  ## Every vertex still present has an incoming arc from another present vertex; following those
  ## arcs backwards from any vertex must therefore close a loop.
  let n = g.vertexCount
  var pred = newSeq[int](n)
  for v in 0 ..< n:
    pred[v] = -1
  var start = -1
  for u in 0 ..< n:
    if removed[u]: continue
    if start < 0: start = u
    for a in g.neighbors(u):
      if not removed[a.target] and pred[a.target] < 0:
        pred[a.target] = u
  var seenAt = newSeq[int](n)
  for v in 0 ..< n:
    seenAt[v] = -1
  var walk: seq[int]
  var current = start
  while seenAt[current] < 0:
    seenAt[current] = walk.len
    walk.add current
    current = pred[current]
  for i in countdown(walk.len - 1, seenAt[current]):
    result.add walk[i]
  var at = 0
  for i, v in result:
    if v < result[at]: at = i
  # Start at the smallest vertex, so the report does not depend on where the walk began.
  result = result[at .. ^1] & result[0 ..< at]

func topoSort*(g: Graph): Result[seq[int], TopoCycle] {.raises: [].} =
  ## All vertices, each before every vertex it has an arc to (GRAPH-TOPO-01), the smallest
  ## vertex first whenever there is a choice (GRAPH-TOPO-03). If the graph has a cycle, the error
  ## holds a real cycle of the graph (GRAPH-TOPO-02). An undirected edge counts as a cycle of two.
  let n = g.vertexCount
  var indegree = newSeq[int](n)
  for u in 0 ..< n:
    for a in g.neighbors(u):
      inc indegree[a.target]
  var ready = initHeapQueue[int]()
  for v in 0 ..< n:
    if indegree[v] == 0:
      ready.push v
  var order: seq[int]
  var removed = newSeq[bool](n)
  while ready.len > 0:
    let u = ready.pop
    order.add u
    removed[u] = true
    for a in g.neighbors(u):
      dec indegree[a.target]
      if indegree[a.target] == 0:
        ready.push a.target
  if order.len == n:
    ok(order, TopoCycle)
  else:
    err(seq[int], TopoCycle(vertices: findCycle(g, removed)))
```

```nim
## Binomial heap: a persistent min-heap whose merge works like binary addition.
##
## A heap is a list of binomial trees in increasing rank, at most one tree per rank, exactly like
## the set bits of n. A tree of rank r has 2^r nodes; linking two trees of rank r gives one of
## rank r+1 (a carry). `insert`, `merge` and `deleteMin` are O(log n) worst case; `insert` is O(1)
## amortized only for ephemeral use (a run of inserts where each version is used once), because
## a persistent program can repeat the longest carry chain from one old version. Use it when you
## want the arithmetic analogy to guide the reasoning and a worst-case O(log n) bound for all
## three operations.

import std/options
import nimcs/ds/cons_list

type
  Tree[T] = ref object
    rank: int
    elem: T
    children: ConsList[Tree[T]]   ## ranks decreasing: rank-1 first, rank 0 last
  BinomialHeap*[T] = object
    trees: ConsList[Tree[T]]      ## ranks increasing, all different
    size: int

func emptyHeap*[T](): BinomialHeap[T] {.raises: [].} =
  BinomialHeap[T]()

func len*[T](h: BinomialHeap[T]): int {.raises: [].} =
  h.size

func isEmpty*[T](h: BinomialHeap[T]): bool {.raises: [].} =
  h.trees.isEmpty

func link[T](a, b: Tree[T]): Tree[T] =
  ## Same rank in, rank + 1 out; the smaller root stays on top.
  if b.elem < a.elem: Tree[T](rank: b.rank + 1, elem: b.elem, children: b.children.cons(a))
  else: Tree[T](rank: a.rank + 1, elem: a.elem, children: a.children.cons(b))

func rankOf[T](ts: ConsList[Tree[T]]): int =
  ts.head.get.rank

func insertTree[T](t: Tree[T]; ts: ConsList[Tree[T]]): ConsList[Tree[T]] =
  if ts.isEmpty or t.rank < rankOf(ts): ts.cons(t)
  else: insertTree(link(t, ts.head.get), ts.tail)

func mergeTrees[T](a, b: ConsList[Tree[T]]): ConsList[Tree[T]] =
  if a.isEmpty: b
  elif b.isEmpty: a
  else:
    let ta = a.head.get
    let tb = b.head.get
    if ta.rank < tb.rank: mergeTrees(a.tail, b).cons(ta)
    elif tb.rank < ta.rank: mergeTrees(a, b.tail).cons(tb)
    else: insertTree(link(ta, tb), mergeTrees(a.tail, b.tail))

func merge*[T](a, b: BinomialHeap[T]): BinomialHeap[T] {.raises: [].} =
  BinomialHeap[T](trees: mergeTrees(a.trees, b.trees), size: a.size + b.size)

func insert*[T](h: BinomialHeap[T]; x: T): BinomialHeap[T] {.raises: [].} =
  BinomialHeap[T](trees: insertTree(Tree[T](rank: 0, elem: x), h.trees), size: h.size + 1)

func minTree[T](ts: ConsList[Tree[T]]): Tree[T] =
  ## `ts` is not empty.
  var best = ts.head.get
  for t in items(ts):
    if t.elem < best.elem: best = t
  best

func findMin*[T](h: BinomialHeap[T]): Option[T] {.raises: [].} =
  if h.isEmpty: none(T) else: some(minTree(h.trees).elem)

func deleteMin*[T](h: BinomialHeap[T]): BinomialHeap[T] {.raises: [].} =
  if h.isEmpty: h
  else:
    let best = minTree(h.trees)
    var others = emptyList[Tree[T]]()
    var removed = false
    for t in items(h.trees):
      if not removed and t == best:   # reference identity: remove exactly this tree
        removed = true
      else:
        others = others.cons(t)
    BinomialHeap[T](trees: mergeTrees(others.reverse, best.children.reverse), size: h.size - 1)

func fromSeq*[T](items: openArray[T]): BinomialHeap[T] {.raises: [].} =
  var h = emptyHeap[T]()
  for x in items:
    h = h.insert(x)
  h

func toSortedSeq*[T](h: BinomialHeap[T]): seq[T] {.raises: [].} =
  var cur = h
  while not cur.isEmpty:
    result.add minTree(cur.trees).elem
    cur = cur.deleteMin

func rankProfile*[T](h: BinomialHeap[T]): seq[int] {.raises: [].} =
  ## The ranks present, increasing. They are the positions of the 1 bits of `len`.
  for t in items(h.trees):
    result.add t.rank

func invariantsHold*[T](h: BinomialHeap[T]): bool {.raises: [].} =
  ## Strictly increasing ranks, each tree heap-ordered with 2^rank nodes.
  func count(t: Tree[T]): int =
    result = 1
    for c in items(t.children):
      result += count(c)
  func ordered(t: Tree[T]): bool =
    result = true
    for c in items(t.children):
      if c.elem < t.elem or not ordered(c): return false
  var prev = -1
  for t in items(h.trees):
    if t.rank <= prev or count(t) != (1 shl t.rank) or not ordered(t): return false
    prev = t.rank
  true
```

```nim
## Bloom filter with value semantics: a compact set that may say "yes" for an absent key but never
## says "no" for a present one.
##
## `add` returns a new filter (the bit array is copied, O(bits / 64)); the old filter is unchanged.
## The `k` bit positions of a key come from two base hashes as `h1 + i * h2` (double hashing), so
## only two hash computations are needed however large `k` is. Both hashes come from `std/hashes`
## on `(salt, key)` pairs and are deterministic; the stride is chosen coprime to the bit count so a
## key sets `min(hashCount, bits)` distinct bits for every bit count. Use it to skip expensive
## lookups for keys that are certainly absent; do not use it when a false positive is unacceptable
## or when you must delete.

import std/[hashes, math, bitops]
import nimcs/fp/result

type
  BloomError* = enum
    beNoBits, beNoHashes, beShapeMismatch
  BloomFilter* = object
    words: seq[uint64]
    bitCount: int
    hashCount: int
    adds: int

func bloomFilter*(bitCount, hashCount: int): Result[BloomFilter, BloomError] {.raises: [].} =
  ## An empty filter of `bitCount` bits using `hashCount` positions per key.
  if bitCount < 1: err(BloomFilter, beNoBits)
  elif hashCount < 1: err(BloomFilter, beNoHashes)
  else:
    ok(BloomFilter(words: newSeq[uint64]((bitCount + 63) div 64), bitCount: bitCount,
      hashCount: hashCount), BloomError)

func bits*(f: BloomFilter): int {.raises: [].} =
  f.bitCount

func hashes*(f: BloomFilter): int {.raises: [].} =
  f.hashCount

func added*(f: BloomFilter): int {.raises: [].} =
  ## Number of `add` calls (repeated keys count each time).
  f.adds

func setBits*(f: BloomFilter): int {.raises: [].} =
  ## Number of bits that are 1.
  for w in f.words:
    result += countSetBits(w)

type Probe = object
  start, stride: int      ## position i is (start + i * stride) mod bitCount

func probeOf[K](f: BloomFilter; key: K): Probe =
  ## The stride is made coprime to the bit count, so the first min(hashCount, bitCount) positions
  ## of a key are distinct for any bit count (an odd stride only guarantees that for powers of two).
  let m = f.bitCount
  var stride = int(uint64(hash((2, key))) mod uint64(m))
  if stride == 0: stride = 1
  while gcd(stride, m) != 1:
    stride = stride mod m + 1          # m > 1 here: gcd(x, 1) is 1, so the loop never runs for m == 1
  Probe(start: int(uint64(hash((1, key))) mod uint64(m)), stride: stride)

func position(f: BloomFilter; p: Probe; i: int): int =
  (p.start + i * p.stride) mod f.bitCount

func add*[K](f: BloomFilter; key: K): BloomFilter {.raises: [].} =
  var words = f.words
  let probe = f.probeOf(key)
  for i in 0 ..< f.hashCount:
    let p = f.position(probe, i)
    words[p div 64] = words[p div 64] or (1'u64 shl (p mod 64))
  BloomFilter(words: words, bitCount: f.bitCount, hashCount: f.hashCount, adds: f.adds + 1)

func mightContain*[K](f: BloomFilter; key: K): bool {.raises: [].} =
  ## False means certainly absent; true means present or a false positive.
  let probe = f.probeOf(key)
  for i in 0 ..< f.hashCount:
    let p = f.position(probe, i)
    if (f.words[p div 64] and (1'u64 shl (p mod 64))) == 0: return false
  true

func merge*(a, b: BloomFilter): Result[BloomFilter, BloomError] {.raises: [].} =
  ## The filter of the union of both key sets; the shapes (bits and hashes) must be equal.
  if a.bitCount != b.bitCount or a.hashCount != b.hashCount:
    err(BloomFilter, beShapeMismatch)
  else:
    var words = a.words
    for i in 0 ..< words.len:
      words[i] = words[i] or b.words[i]
    ok(BloomFilter(words: words, bitCount: a.bitCount, hashCount: a.hashCount,
      adds: a.adds + b.adds), BloomError)

func sameBits*(a, b: BloomFilter): bool {.raises: [].} =
  ## Equal shape and equal bit array (the `added` counters are ignored).
  a.bitCount == b.bitCount and a.hashCount == b.hashCount and a.words == b.words
```

```nim
## Persistent singly linked list (a "cons list").
##
## Every update returns a new list and leaves the old one valid; lists share their tails through
## `ref` to immutable nodes, so `xs.cons(x)` is O(1) in time and space and two lists built from the
## same `xs` share all of `xs`. Use it as a stack, as the spine of recursive algorithms, or as the
## building block of the queues and heaps in this package; reach for `seq` when you need indexed
## access or cache-friendly scans.

import std/options

type
  NodeObj[T] = object
    head: T
    tail: ConsList[T]
  Node[T] = ref NodeObj[T]
  ConsList*[T] = object
    ## The empty list is `default(ConsList[T])`; there is no nil to check at the call site.
    node: Node[T]

proc `=destroy`[T](n: var NodeObj[T]) =
  ## Frees a long chain in a loop. The default destructor would recurse once per node and
  ## overflow the stack on a list of a few hundred thousand nodes. A node that another list still
  ## reaches (`isUniqueRef` is false) is left alone: its last owner frees it.
  var next = move(n.tail.node)
  while not next.isNil and isUniqueRef(next):
    let following = move(next.tail.node)   # `next` now has no tail, so freeing it is O(1)
    next = following
  reset(n.head)

func emptyList*[T](): ConsList[T] {.raises: [].} =
  ConsList[T]()

func isEmpty*[T](xs: ConsList[T]): bool {.raises: [].} =
  xs.node.isNil

func cons*[T](xs: ConsList[T]; x: T): ConsList[T] {.raises: [].} =
  ## New list with `x` in front; `xs` is untouched and shared.
  ConsList[T](node: Node[T](head: x, tail: xs))

func head*[T](xs: ConsList[T]): Option[T] {.raises: [].} =
  if xs.isEmpty: none(T) else: some(xs.node.head)

func tail*[T](xs: ConsList[T]): ConsList[T] {.raises: [].} =
  ## The list without its first element; the tail of the empty list is the empty list.
  if xs.isEmpty: xs else: xs.node.tail

func isUnshared*[T](xs: ConsList[T]): bool {.raises: [].} =
  ## True when no other list or variable reaches the first cell of `xs`, so that dropping `xs`
  ## frees it. Structures that tear themselves down iteratively use this to stop at shared cells.
  xs.isEmpty or isUniqueRef(xs.node)

func sharesNode*[T](a, b: ConsList[T]): bool {.raises: [].} =
  ## True when both lists start at the same node in memory (reference identity).
  a.node == b.node

iterator items*[T](xs: ConsList[T]): T {.raises: [].} =
  var cur = xs
  while not cur.isEmpty:
    yield cur.node.head
    cur = cur.node.tail

func foldLeft*[T, A](xs: ConsList[T]; init: A; f: proc(acc: A; x: T): A {.noSideEffect, raises: [].}): A {.raises: [].} =
  ## Left fold: `foldLeft([1,2,3], z, f) == f(f(f(z,1),2),3)`.
  var acc = init
  for x in items(xs):
    acc = f(acc, x)
  acc

func len*[T](xs: ConsList[T]): int {.raises: [].} =
  var n = 0
  for _ in items(xs):
    inc n
  n

func toSeq*[T](xs: ConsList[T]): seq[T] {.raises: [].} =
  for x in items(xs):
    result.add x

func reverse*[T](xs: ConsList[T]): ConsList[T] {.raises: [].} =
  var acc = emptyList[T]()
  for x in items(xs):
    acc = acc.cons(x)
  acc

func fromSeq*[T](items: openArray[T]): ConsList[T] {.raises: [].} =
  var acc = emptyList[T]()
  for i in countdown(items.high, 0):
    acc = acc.cons(items[i])
  acc

func append*[T](a, b: ConsList[T]): ConsList[T] {.raises: [].} =
  ## `a ++ b`: copies the spine of `a` (O(len a)) and shares all of `b`.
  var acc = b
  for x in items(a.reverse):
    acc = acc.cons(x)
  acc

func map*[T, U](xs: ConsList[T]; f: proc(x: T): U {.noSideEffect, raises: [].}): ConsList[U] {.raises: [].} =
  var acc = emptyList[U]()
  for x in items(xs):
    acc = acc.cons(f(x))
  acc.reverse

func `==`*[T](a, b: ConsList[T]): bool {.raises: [].} =
  a.toSeq == b.toSeq
```

```nim
## Hash array mapped trie (HAMT): a persistent unordered map with O(log32 n) operations.
##
## The hash of a key is read five bits at a time; each trie node stores a 32-bit bitmap saying
## which of its 32 slots are used and keeps only the used slots in a compact `seq`. A slot holds
## a single pair, a child node, or (when all 60+ hash bits agree) a bucket of colliding pairs.
## `put` and `remove` copy one root-to-leaf path and share the rest. The hash comes from
## `std/hashes` (`hash(key)`), which is deterministic for ints and strings; iteration order
## follows hash bits, so it is never exposed: the only way to list entries is `toSortedSeq`.
## Use it for large maps that are updated functionally and need no key order; use `rb_tree` when
## you need ordered traversal.

import std/[hashes, options, algorithm, bitops]

const
  bits = 5
  mask = 31'u64
  maxLevel = 12     ## levels 0..12 consume 65 bits; deeper than that means identical hashes

type
  SlotKind = enum
    skPair, skNode, skBucket
  Node[K, V] = ref object
    bitmap: uint32
    slots: seq[Slot[K, V]]
  Slot[K, V] = object
    case kind: SlotKind
    of skPair:
      key: K
      val: V
    of skNode:
      child: Node[K, V]
    of skBucket:
      pairs: seq[(K, V)]
  Hamt*[K, V] = object
    root: Node[K, V]
    size: int

func emptyHamt*[K, V](): Hamt[K, V] {.raises: [].} =
  Hamt[K, V](root: Node[K, V]())

func len*[K, V](m: Hamt[K, V]): int {.raises: [].} =
  m.size

func chunk(h: uint64; level: int): int =
  int((h shr (level * bits)) and mask)

func positionOf(bitmap: uint32; idx: int): int =
  ## Index into `slots` of the slot for chunk `idx`.
  countSetBits(bitmap and ((1'u32 shl idx) - 1))

func hashOf[K](key: K): uint64 =
  uint64(hash(key))

func pairSlot[K, V](key: K; val: V): Slot[K, V] =
  Slot[K, V](kind: skPair, key: key, val: val)

func joinPairs[K, V](k1: K; v1: V; k2: K; v2: V; level: int): Slot[K, V] =
  ## A slot holding two pairs with different keys, as seen from a node at `level - 1`.
  if level > maxLevel:
    Slot[K, V](kind: skBucket, pairs: @[(k1, v1), (k2, v2)])
  else:
    let i1 = chunk(hashOf(k1), level)
    let i2 = chunk(hashOf(k2), level)
    if i1 == i2:
      Slot[K, V](kind: skNode, child: Node[K, V](bitmap: 1'u32 shl i1,
        slots: @[joinPairs(k1, v1, k2, v2, level + 1)]))
    elif i1 < i2:
      Slot[K, V](kind: skNode, child: Node[K, V](bitmap: (1'u32 shl i1) or (1'u32 shl i2),
        slots: @[pairSlot(k1, v1), pairSlot(k2, v2)]))
    else:
      Slot[K, V](kind: skNode, child: Node[K, V](bitmap: (1'u32 shl i1) or (1'u32 shl i2),
        slots: @[pairSlot(k2, v2), pairSlot(k1, v1)]))

func putInto[K, V](n: Node[K, V]; key: K; h: uint64; val: V; level: int): Node[K, V] =
  let idx = chunk(h, level)
  let bit = 1'u32 shl idx
  let pos = positionOf(n.bitmap, idx)
  var slots = n.slots
  if (n.bitmap and bit) == 0:
    slots.insert(pairSlot(key, val), pos)
    return Node[K, V](bitmap: n.bitmap or bit, slots: slots)
  let slot = n.slots[pos]
  case slot.kind
  of skPair:
    slots[pos] =
      if slot.key == key: pairSlot(key, val)
      else: joinPairs(slot.key, slot.val, key, val, level + 1)
  of skNode:
    slots[pos] = Slot[K, V](kind: skNode, child: putInto(slot.child, key, h, val, level + 1))
  of skBucket:
    var pairs = slot.pairs
    var found = false
    for p in pairs.mitems:
      if p[0] == key:
        p[1] = val
        found = true
    if not found: pairs.add (key, val)
    slots[pos] = Slot[K, V](kind: skBucket, pairs: pairs)
  Node[K, V](bitmap: n.bitmap, slots: slots)

func get*[K, V](m: Hamt[K, V]; key: K): Option[V] {.raises: [].} =
  if m.root.isNil: return none(V)
  let h = hashOf(key)
  var n = m.root
  var level = 0
  while true:
    let idx = chunk(h, level)
    if (n.bitmap and (1'u32 shl idx)) == 0: return none(V)
    let slot = n.slots[positionOf(n.bitmap, idx)]
    case slot.kind
    of skPair:
      return if slot.key == key: some(slot.val) else: none(V)
    of skNode:
      n = slot.child
      inc level
    of skBucket:
      for p in slot.pairs:
        if p[0] == key: return some(p[1])
      return none(V)

func contains*[K, V](m: Hamt[K, V]; key: K): bool {.raises: [].} =
  m.get(key).isSome

func put*[K, V](m: Hamt[K, V]; key: K; val: V): Hamt[K, V] {.raises: [].} =
  ## Inserts or replaces the value of `key`.
  let root = if m.root.isNil: Node[K, V]() else: m.root
  Hamt[K, V](root: putInto(root, key, hashOf(key), val, 0),
    size: if m.contains(key): m.size else: m.size + 1)

func removeFrom[K, V](n: Node[K, V]; key: K; h: uint64; level: int): Node[K, V] =
  ## Returns nil when the node becomes empty. Singleton nodes are not collapsed into their parent.
  let idx = chunk(h, level)
  let bit = 1'u32 shl idx
  if (n.bitmap and bit) == 0: return n
  let pos = positionOf(n.bitmap, idx)
  let slot = n.slots[pos]
  var slots = n.slots
  var bitmap = n.bitmap
  case slot.kind
  of skPair:
    if slot.key != key: return n
    slots.delete(pos)
    bitmap = bitmap and not bit
  of skNode:
    let child = removeFrom(slot.child, key, h, level + 1)
    if child == slot.child: return n
    if child.isNil:
      slots.delete(pos)
      bitmap = bitmap and not bit
    else:
      slots[pos] = Slot[K, V](kind: skNode, child: child)
  of skBucket:
    var pairs: seq[(K, V)]
    for p in slot.pairs:
      if p[0] != key: pairs.add p
    if pairs.len == slot.pairs.len: return n
    if pairs.len == 0:
      slots.delete(pos)
      bitmap = bitmap and not bit
    else:
      slots[pos] = Slot[K, V](kind: skBucket, pairs: pairs)
  if slots.len == 0: nil
  else: Node[K, V](bitmap: bitmap, slots: slots)

func remove*[K, V](m: Hamt[K, V]; key: K): Hamt[K, V] {.raises: [].} =
  ## The map without `key`; unchanged (and the same value) when the key is absent.
  if not m.contains(key): return m
  let root = removeFrom(m.root, key, hashOf(key), 0)
  Hamt[K, V](root: if root.isNil: Node[K, V]() else: root, size: m.size - 1)

func collect[K, V](n: Node[K, V]; into: var seq[(K, V)]) =
  for slot in n.slots:
    case slot.kind
    of skPair: into.add (slot.key, slot.val)
    of skNode: collect(slot.child, into)
    of skBucket:
      for p in slot.pairs:
        into.add p

func toSortedSeq*[K, V](m: Hamt[K, V]): seq[(K, V)] {.raises: [].} =
  ## All entries ordered by key. The trie's own order depends on the hash and is never exposed.
  if m.root.isNil: return
  collect(m.root, result)
  result.sort(proc(a, b: (K, V)): int = cmp(a[0], b[0]))

func fromPairs*[K, V](pairs: openArray[(K, V)]): Hamt[K, V] {.raises: [].} =
  ## Later pairs replace earlier ones with the same key.
  var m = emptyHamt[K, V]()
  for (k, v) in pairs:
    m = m.put(k, v)
  m
```

```nim
## Leftist heap: a mergeable persistent min-heap.
##
## A binary tree with the heap order (a parent is not larger than its children) and the leftist
## property: the right spine is never longer than the left one. All work follows the right spine,
## so `merge`, `insert` and `deleteMin` are O(log n) worst case. Use it when two priority queues
## must be combined often; use `pairing_heap` for lower constants in practice.

import std/options

type
  NodeObj[T] = object
    rank: int          ## length of the right spine
    elem: T
    left, right: Node[T]
  Node[T] = ref NodeObj[T]
  LeftistHeap*[T] = object
    root: Node[T]
    size: int

proc `=destroy`[T](n: var NodeObj[T]) =
  ## The left spine can be as long as the heap (descending inserts), so the default destructor
  ## would recurse once per node. A work list frees the nodes this heap owns alone; a node still
  ## reachable from another heap (`isUniqueRef` is false) is left to its last owner.
  var pending: seq[Node[T]]
  if not n.left.isNil: pending.add move(n.left)
  if not n.right.isNil: pending.add move(n.right)
  while pending.len > 0:
    let c = pending.pop
    if isUniqueRef(c):
      if not c.left.isNil: pending.add move(c.left)
      if not c.right.isNil: pending.add move(c.right)
  reset(n.elem)

func emptyHeap*[T](): LeftistHeap[T] {.raises: [].} =
  LeftistHeap[T]()

func len*[T](h: LeftistHeap[T]): int {.raises: [].} =
  h.size

func isEmpty*[T](h: LeftistHeap[T]): bool {.raises: [].} =
  h.root.isNil

func rankOf[T](n: Node[T]): int =
  if n.isNil: 0 else: n.rank

func make[T](x: T; a, b: Node[T]): Node[T] =
  ## Puts the node with the larger rank on the left.
  if rankOf(a) >= rankOf(b): Node[T](rank: rankOf(b) + 1, elem: x, left: a, right: b)
  else: Node[T](rank: rankOf(a) + 1, elem: x, left: b, right: a)

func mergeNodes[T](a, b: Node[T]): Node[T] =
  if a.isNil: b
  elif b.isNil: a
  elif b.elem < a.elem: make(b.elem, b.left, mergeNodes(a, b.right))
  else: make(a.elem, a.left, mergeNodes(a.right, b))

func merge*[T](a, b: LeftistHeap[T]): LeftistHeap[T] {.raises: [].} =
  LeftistHeap[T](root: mergeNodes(a.root, b.root), size: a.size + b.size)

func insert*[T](h: LeftistHeap[T]; x: T): LeftistHeap[T] {.raises: [].} =
  h.merge(LeftistHeap[T](root: Node[T](rank: 1, elem: x), size: 1))

func findMin*[T](h: LeftistHeap[T]): Option[T] {.raises: [].} =
  if h.isEmpty: none(T) else: some(h.root.elem)

func deleteMin*[T](h: LeftistHeap[T]): LeftistHeap[T] {.raises: [].} =
  ## The heap without its minimum; the empty heap stays empty.
  if h.isEmpty: h
  else: LeftistHeap[T](root: mergeNodes(h.root.left, h.root.right), size: h.size - 1)

func fromSeq*[T](items: openArray[T]): LeftistHeap[T] {.raises: [].} =
  var h = emptyHeap[T]()
  for x in items:
    h = h.insert(x)
  h

func toSortedSeq*[T](h: LeftistHeap[T]): seq[T] {.raises: [].} =
  ## Heap sort: repeatedly take the minimum.
  var cur = h
  while not cur.isEmpty:
    result.add cur.root.elem
    cur = cur.deleteMin

func invariantsHold*[T](h: LeftistHeap[T]): bool {.raises: [].} =
  ## Heap order, leftist property and correct stored ranks, checked over the whole tree.
  func ok(n: Node[T]): bool =
    if n.isNil: true
    else:
      (n.left.isNil or not (n.left.elem < n.elem)) and
        (n.right.isNil or not (n.right.elem < n.elem)) and
        rankOf(n.left) >= rankOf(n.right) and n.rank == rankOf(n.right) + 1 and
        ok(n.left) and ok(n.right)
  ok(h.root)
```

```nim
## Pairing heap: a mergeable persistent min-heap with a very simple shape.
##
## A node holds its element and a list of child heaps. `merge` makes the larger root a child of the
## smaller one in O(1); `deleteMin` merges the children pairwise from left to right and then
## folds the results from right to left, which is O(log n) amortized (ephemeral use). Use it as a
## default priority queue in functional code; see `leftist_heap` for a worst-case bound.

import std/options
import nimcs/ds/cons_list

type
  NodeObj[T] = object
    elem: T
    children: ConsList[Node[T]]
  Node[T] = ref NodeObj[T]
  PairingHeap*[T] = object
    root: Node[T]
    size: int

proc `=destroy`[T](n: var NodeObj[T]) =
  ## Dismantles a deep heap with a work list instead of one recursive call per level (descending
  ## inserts build a chain as deep as the heap is large). A node still reachable from another
  ## heap (`isUniqueRef` is false) is left to its last owner.
  var pending = @[move(n.children)]
  while pending.len > 0:
    var level = pending.pop
    while not level.isEmpty and level.isUnshared:
      var kid: Node[T]
      for k in items(level):    # `head` would leave an Option temporary holding a second reference
        kid = k
        break
      level = level.tail     # frees the first cell, leaving `kid` as the only owner if it was alone
      if isUniqueRef(kid):
        pending.add move(kid.children)
  reset(n.elem)

func emptyHeap*[T](): PairingHeap[T] {.raises: [].} =
  PairingHeap[T]()

func len*[T](h: PairingHeap[T]): int {.raises: [].} =
  h.size

func isEmpty*[T](h: PairingHeap[T]): bool {.raises: [].} =
  h.root.isNil

func link[T](a, b: Node[T]): Node[T] =
  if b.elem < a.elem: Node[T](elem: b.elem, children: b.children.cons(a))
  else: Node[T](elem: a.elem, children: a.children.cons(b))

func merge*[T](a, b: PairingHeap[T]): PairingHeap[T] {.raises: [].} =
  if a.isEmpty: b
  elif b.isEmpty: a
  else: PairingHeap[T](root: link(a.root, b.root), size: a.size + b.size)

func insert*[T](h: PairingHeap[T]; x: T): PairingHeap[T] {.raises: [].} =
  h.merge(PairingHeap[T](root: Node[T](elem: x), size: 1))

func findMin*[T](h: PairingHeap[T]): Option[T] {.raises: [].} =
  if h.isEmpty: none(T) else: some(h.root.elem)

func mergePairs[T](children: ConsList[Node[T]]): Node[T] =
  ## Two passes, iterative so that a wide node cannot overflow the stack.
  var paired: seq[Node[T]]
  var cur = children
  while not cur.isEmpty:
    let first = cur.head.get
    let rest = cur.tail
    if rest.isEmpty:
      paired.add first
      cur = rest
    else:
      paired.add link(first, rest.head.get)
      cur = rest.tail
  var acc: Node[T] = nil
  for i in countdown(paired.high, 0):
    acc = if acc.isNil: paired[i] else: link(paired[i], acc)
  acc

func deleteMin*[T](h: PairingHeap[T]): PairingHeap[T] {.raises: [].} =
  if h.isEmpty: h
  else: PairingHeap[T](root: mergePairs(h.root.children), size: h.size - 1)

func fromSeq*[T](items: openArray[T]): PairingHeap[T] {.raises: [].} =
  var h = emptyHeap[T]()
  for x in items:
    h = h.insert(x)
  h

func toSortedSeq*[T](h: PairingHeap[T]): seq[T] {.raises: [].} =
  var cur = h
  while not cur.isEmpty:
    result.add cur.root.elem
    cur = cur.deleteMin
```

```nim
## Persistent vector: a 32-way trie giving O(log32 n) indexed `get`, `updated` and `push`.
##
## Elements live in leaves of up to 32 items; interior nodes hold up to 32 children; the index is
## read five bits at a time from the top. An update copies the one path from the root to the
## leaf (at most 7 nodes for 2^32 elements) and shares everything else, so the old vector stays
## valid. Use it for large indexed collections that are updated functionally; use `skew_list`
## when you push and pop at the front. The tail optimisation that real implementations add (an
## unshared buffer at the end) is left out so the shape stays easy to read.

import std/options

const
  bits = 5
  width = 1 shl bits
  mask = width - 1

type
  Node[T] = ref object
    items: seq[T]            ## filled in leaves only
    kids: seq[Node[T]]       ## filled in interior nodes only
  PVector*[T] = object
    root: Node[T]
    shift: int               ## 0 when the root is a leaf, else 5 * (levels above the leaves)
    size: int

func emptyVector*[T](): PVector[T] {.raises: [].} =
  PVector[T](root: Node[T]())

func len*[T](v: PVector[T]): int {.raises: [].} =
  v.size

func isEmpty*[T](v: PVector[T]): bool {.raises: [].} =
  v.size == 0

func capacity[T](v: PVector[T]): int =
  1 shl (v.shift + bits)

func newPath[T](level: int; x: T): Node[T] =
  ## A chain of nodes from `level` down to a leaf holding only `x`.
  if level == 0: Node[T](items: @[x])
  else: Node[T](kids: @[newPath(level - bits, x)])

func pushInto[T](n: Node[T]; level, index: int; x: T): Node[T] =
  if level == 0:
    Node[T](items: n.items & @[x])
  else:
    let slot = (index shr level) and mask
    if slot < n.kids.len:
      var kids = n.kids
      kids[slot] = pushInto(n.kids[slot], level - bits, index, x)
      Node[T](kids: kids)
    else:
      Node[T](kids: n.kids & @[newPath(level - bits, x)])

func push*[T](v: PVector[T]; x: T): PVector[T] {.raises: [].} =
  ## Appends `x` at index `len`.
  let base = if v.root.isNil: emptyVector[T]() else: v
  if base.size == base.capacity:
    PVector[T](root: Node[T](kids: @[base.root, newPath(base.shift, x)]),
      shift: base.shift + bits, size: base.size + 1)
  else:
    PVector[T](root: pushInto(base.root, base.shift, base.size, x), shift: base.shift,
      size: base.size + 1)

func get*[T](v: PVector[T]; i: int): Option[T] {.raises: [].} =
  if i < 0 or i >= v.size: return none(T)
  var n = v.root
  var level = v.shift
  while level > 0:
    n = n.kids[(i shr level) and mask]
    level -= bits
  some(n.items[i and mask])

func setInto[T](n: Node[T]; level, i: int; x: T): Node[T] =
  if level == 0:
    var items = n.items
    items[i and mask] = x
    Node[T](items: items)
  else:
    var kids = n.kids
    let slot = (i shr level) and mask
    kids[slot] = setInto(n.kids[slot], level - bits, i, x)
    Node[T](kids: kids)

func updated*[T](v: PVector[T]; i: int; x: T): Option[PVector[T]] {.raises: [].} =
  ## A copy with index `i` replaced; none when out of range.
  if i < 0 or i >= v.size: none(PVector[T])
  else: some(PVector[T](root: setInto(v.root, v.shift, i, x), shift: v.shift, size: v.size))

func toSeq*[T](v: PVector[T]): seq[T] {.raises: [].} =
  for i in 0 ..< v.size:
    result.add v.get(i).get

func fromSeq*[T](items: openArray[T]): PVector[T] {.raises: [].} =
  var v = emptyVector[T]()
  for x in items:
    v = v.push(x)
  v

func depth*[T](v: PVector[T]): int {.raises: [].} =
  ## Number of nodes on a root-to-leaf path.
  v.shift div bits + 1
```

```nim
## Persistent red-black tree: an ordered map (`RbMap`) and an ordered set (`RbSet`).
##
## A binary search tree whose nodes are coloured so that the root is black, no red node has a red
## child, and every path from a node to a leaf holds the same number of black nodes. Those rules
## keep the height at most 2 log2(n + 1), so `put`, `get` and `contains` are O(log n) worst case.
## `put` copies only the path it walks (O(log n) new nodes) and shares the rest with the old tree,
## which stays valid. Use it for ordered iteration, range-like queries and a deterministic order;
## use `hamt` for unordered lookup. Deletion is not provided: its case analysis is longer than is worth showing here;
## rebuild from `toSeq` without the key, or use `hamt` when you need `remove`.

import std/options

type
  Color = enum
    cRed, cBlack
  Node[K, V] = ref object
    red: bool
    key: K
    val: V
    left, right: Node[K, V]
  RbMap*[K, V] = object
    root: Node[K, V]
    size: int
  Unit = object        ## the value type of a set: no payload
  RbSet*[K] = object
    items: RbMap[K, Unit]

func emptyMap*[K, V](): RbMap[K, V] {.raises: [].} =
  RbMap[K, V]()

func len*[K, V](m: RbMap[K, V]): int {.raises: [].} =
  m.size

func isRed[K, V](n: Node[K, V]): bool =
  not n.isNil and n.red

func mk[K, V](red: bool; key: K; val: V; l, r: Node[K, V]): Node[K, V] =
  Node[K, V](red: red, key: key, val: val, left: l, right: r)

func balance[K, V](key: K; val: V; l, r: Node[K, V]): Node[K, V] =
  ## Builds a black node and repairs a red-red violation among its two upper levels (Okasaki).
  if isRed(l) and isRed(l.left):
    mk(true, l.key, l.val, mk(false, l.left.key, l.left.val, l.left.left, l.left.right),
      mk(false, key, val, l.right, r))
  elif isRed(l) and isRed(l.right):
    let m = l.right
    mk(true, m.key, m.val, mk(false, l.key, l.val, l.left, m.left), mk(false, key, val, m.right, r))
  elif isRed(r) and isRed(r.left):
    let m = r.left
    mk(true, m.key, m.val, mk(false, key, val, l, m.left), mk(false, r.key, r.val, m.right, r.right))
  elif isRed(r) and isRed(r.right):
    mk(true, r.key, r.val, mk(false, key, val, l, r.left),
      mk(false, r.right.key, r.right.val, r.right.left, r.right.right))
  else:
    mk(false, key, val, l, r)

func ins[K, V](n: Node[K, V]; key: K; val: V): Node[K, V] =
  if n.isNil: mk(true, key, val, nil, nil)
  elif key < n.key:
    if n.red: mk(true, n.key, n.val, ins(n.left, key, val), n.right)
    else: balance(n.key, n.val, ins(n.left, key, val), n.right)
  elif n.key < key:
    if n.red: mk(true, n.key, n.val, n.left, ins(n.right, key, val))
    else: balance(n.key, n.val, n.left, ins(n.right, key, val))
  else:
    mk(n.red, key, val, n.left, n.right)

func find[K, V](n: Node[K, V]; key: K): Node[K, V] =
  var cur = n
  while not cur.isNil:
    if key < cur.key: cur = cur.left
    elif cur.key < key: cur = cur.right
    else: return cur
  nil

func get*[K, V](m: RbMap[K, V]; key: K): Option[V] {.raises: [].} =
  let n = find(m.root, key)
  if n.isNil: none(V) else: some(n.val)

func contains*[K, V](m: RbMap[K, V]; key: K): bool {.raises: [].} =
  not find(m.root, key).isNil

func put*[K, V](m: RbMap[K, V]; key: K; val: V): RbMap[K, V] {.raises: [].} =
  ## Inserts or replaces the value of `key`.
  let grown = ins(m.root, key, val)
  let root = mk(false, grown.key, grown.val, grown.left, grown.right)  # the root is always black
  RbMap[K, V](root: root, size: if m.contains(key): m.size else: m.size + 1)

func graft[K, V](color: Color; key: K; val: V; left, right: RbMap[K, V]): RbMap[K, V] {.raises: [].} =
  ## Test-only: a node of the given colour over two subtrees, with no rebalancing and no check that
  ## the result is a valid red-black tree. Not exported, so no caller can build an invalid map; the
  ## tests reach it through `import nimcs/ds/rb_tree {.all.}` to show `invariantsHold` saying no.
  RbMap[K, V](root: mk(color == cRed, key, val, left.root, right.root),
    size: left.size + right.size + 1)

func toSeq*[K, V](m: RbMap[K, V]): seq[(K, V)] {.raises: [].} =
  ## Key/value pairs in increasing key order (in-order walk, explicit stack).
  var stack: seq[Node[K, V]]
  var cur = m.root
  while not cur.isNil or stack.len > 0:
    while not cur.isNil:
      stack.add cur
      cur = cur.left
    let n = stack.pop
    result.add (n.key, n.val)
    cur = n.right

func fromPairs*[K, V](pairs: openArray[(K, V)]): RbMap[K, V] {.raises: [].} =
  ## Later pairs replace earlier ones with the same key.
  var m = emptyMap[K, V]()
  for (k, v) in pairs:
    m = m.put(k, v)
  m

func height*[K, V](m: RbMap[K, V]): int {.raises: [].} =
  func h(n: Node[K, V]): int =
    if n.isNil: 0 else: 1 + max(h(n.left), h(n.right))
  h(m.root)

func invariantsHold*[K, V](m: RbMap[K, V]): bool {.raises: [].} =
  ## Black root, no red node with a red child, equal black height on all paths, every key strictly
  ## between the keys of the nearest ancestors on each side (so `get` finds it), and a stored size
  ## that matches the node count.
  func blackHeight(n, lo, hi: Node[K, V]): int =   # -1 when a rule is broken below `n`
    if n.isNil: return 1
    if not lo.isNil and not (lo.key < n.key): return -1
    if not hi.isNil and not (n.key < hi.key): return -1
    let l = blackHeight(n.left, lo, n)
    let r = blackHeight(n.right, n, hi)
    if l < 0 or r < 0 or l != r: return -1
    if n.red and (isRed(n.left) or isRed(n.right)): return -1
    l + (if n.red: 0 else: 1)
  not isRed(m.root) and blackHeight(m.root, nil, nil) > 0 and m.toSeq.len == m.size

func emptySet*[K](): RbSet[K] {.raises: [].} =
  RbSet[K]()

func len*[K](s: RbSet[K]): int {.raises: [].} =
  s.items.len

func incl*[K](s: RbSet[K]; key: K): RbSet[K] {.raises: [].} =
  RbSet[K](items: s.items.put(key, Unit()))

func contains*[K](s: RbSet[K]; key: K): bool {.raises: [].} =
  s.items.contains(key)

func toSeq*[K](s: RbSet[K]): seq[K] {.raises: [].} =
  for (k, _) in s.items.toSeq:
    result.add k

func fromSeq*[K](keys: openArray[K]): RbSet[K] {.raises: [].} =
  var s = emptySet[K]()
  for k in keys:
    s = s.incl(k)
  s

func invariantsHold*[K](s: RbSet[K]): bool {.raises: [].} =
  s.items.invariantsHold
```

```nim
## Immutable segment tree over a monoid: range queries and point updates in O(log n).
##
## A monoid is an associative `combine` with an `identity`. The tree stores, in every node, the
## combination of the elements below it, so a query over a half-open range [l, r) combines at most
## about 2 log2(n) stored values. A point update copies one root-to-leaf path and shares the rest,
## so the old tree stays valid. Because only associativity is required (not commutativity), the
## order of elements is respected: string concatenation works. Use it for repeated range sums,
## minima, gcds or any associative summary over an array with updates; use a prefix-sum array when
## the data never changes.

import std/options

type
  Monoid*[T] = object
    identity*: T
    combine*: proc(a, b: T): T {.noSideEffect, raises: [].}
  Node[T] = ref object
    value: T
    left, right: Node[T]     ## nil in leaves
  SegTree*[T] = object
    monoid: Monoid[T]
    root: Node[T]
    size: int

func initMonoid*[T](identity: T; combine: proc(a, b: T): T {.noSideEffect, raises: [].}): Monoid[T] {.raises: [].} =
  Monoid[T](identity: identity, combine: combine)

func buildNode[T](m: Monoid[T]; items: openArray[T]; lo, hi: int): Node[T] =
  ## Node for items[lo ..< hi], hi > lo.
  if hi - lo == 1: Node[T](value: items[lo])
  else:
    let mid = (lo + hi) div 2
    let l = buildNode(m, items, lo, mid)
    let r = buildNode(m, items, mid, hi)
    Node[T](value: m.combine(l.value, r.value), left: l, right: r)

func fromSeq*[T](m: Monoid[T]; items: openArray[T]): SegTree[T] {.raises: [].} =
  if items.len == 0: SegTree[T](monoid: m, size: 0)
  else: SegTree[T](monoid: m, root: buildNode(m, items, 0, items.len), size: items.len)

func len*[T](t: SegTree[T]): int {.raises: [].} =
  t.size

func queryNode[T](m: Monoid[T]; n: Node[T]; lo, hi, l, r: int): T =
  ## Combination of the elements of [lo, hi) that fall inside [l, r).
  if r <= lo or hi <= l: m.identity
  elif l <= lo and hi <= r: n.value
  else:
    let mid = (lo + hi) div 2
    m.combine(queryNode(m, n.left, lo, mid, l, r), queryNode(m, n.right, mid, hi, l, r))

func query*[T](t: SegTree[T]; l, r: int): Option[T] {.raises: [].} =
  ## Combination of elements l, l+1, ..., r-1 in order. An empty range gives the identity; a range
  ## outside 0 <= l <= r <= len gives none.
  if l < 0 or r > t.size or l > r: none(T)
  elif l == r: some(t.monoid.identity)
  else: some(queryNode(t.monoid, t.root, 0, t.size, l, r))

func updateNode[T](m: Monoid[T]; n: Node[T]; lo, hi, i: int; x: T): Node[T] =
  if hi - lo == 1: Node[T](value: x)
  else:
    let mid = (lo + hi) div 2
    let l = if i < mid: updateNode(m, n.left, lo, mid, i, x) else: n.left
    let r = if i < mid: n.right else: updateNode(m, n.right, mid, hi, i, x)
    Node[T](value: m.combine(l.value, r.value), left: l, right: r)

func updated*[T](t: SegTree[T]; i: int; x: T): Option[SegTree[T]] {.raises: [].} =
  ## A tree with element `i` replaced by `x`; none when out of range.
  if i < 0 or i >= t.size: none(SegTree[T])
  else: some(SegTree[T](monoid: t.monoid, root: updateNode(t.monoid, t.root, 0, t.size, i, x), size: t.size))

func get*[T](t: SegTree[T]; i: int): Option[T] {.raises: [].} =
  if i < 0 or i >= t.size: none(T)
  else: t.query(i, i + 1)

func total*[T](t: SegTree[T]): T {.raises: [].} =
  ## Combination of all elements (the identity when empty).
  if t.size == 0: t.monoid.identity else: t.root.value
```

```nim
## Skew-binary random-access list: a persistent sequence with O(1) `cons`/`head`/`tail` and
## O(log n) indexed `get` and `updated`.
##
## The list is a short spine of complete binary trees whose sizes are of the form 2^k - 1, in
## non-decreasing order with at most the first two equal (a skew-binary number). Consing links the
## first two trees when they have equal size, otherwise starts a new one-element tree; that is why
## no carry ever ripples. Use it when you need a stack that also supports indexing and
## functional update; use `pvector` for append-at-the-end with indexing, `cons_list` when you never index.

import std/options
import nimcs/ds/cons_list

type
  Tree[T] = ref object
    elem: T
    left, right: Tree[T]    ## both nil for a single element
  Entry[T] = object
    weight: int             ## number of elements, 2^k - 1
    tree: Tree[T]
  SkewList*[T] = object
    spine: ConsList[Entry[T]]
    size: int

func emptySkew*[T](): SkewList[T] {.raises: [].} =
  SkewList[T]()

func len*[T](xs: SkewList[T]): int {.raises: [].} =
  xs.size

func isEmpty*[T](xs: SkewList[T]): bool {.raises: [].} =
  xs.size == 0

func cons*[T](xs: SkewList[T]; x: T): SkewList[T] {.raises: [].} =
  let first = xs.spine.head
  let second = xs.spine.tail.head
  if first.isSome and second.isSome and first.get.weight == second.get.weight:
    let w = first.get.weight
    let linked = Entry[T](weight: 1 + 2 * w,
      tree: Tree[T](elem: x, left: first.get.tree, right: second.get.tree))
    SkewList[T](spine: xs.spine.tail.tail.cons(linked), size: xs.size + 1)
  else:
    SkewList[T](spine: xs.spine.cons(Entry[T](weight: 1, tree: Tree[T](elem: x))), size: xs.size + 1)

func head*[T](xs: SkewList[T]): Option[T] {.raises: [].} =
  let first = xs.spine.head
  if first.isNone: none(T) else: some(first.get.tree.elem)

func tail*[T](xs: SkewList[T]): SkewList[T] {.raises: [].} =
  ## The list without its first element; the tail of the empty list is the empty list.
  let first = xs.spine.head
  if first.isNone: xs
  else:
    let e = first.get
    let rest = xs.spine.tail
    if e.weight == 1: SkewList[T](spine: rest, size: xs.size - 1)
    else:
      let half = e.weight div 2
      SkewList[T](spine: rest.cons(Entry[T](weight: half, tree: e.tree.right))
        .cons(Entry[T](weight: half, tree: e.tree.left)), size: xs.size - 1)

func lookupTree[T](w: int; t: Tree[T]; i: int): T =
  ## Requires 0 <= i < w.
  if i == 0: t.elem
  else:
    let half = w div 2
    if i <= half: lookupTree(half, t.left, i - 1)
    else: lookupTree(half, t.right, i - 1 - half)

func updateTree[T](w: int; t: Tree[T]; i: int; x: T): Tree[T] =
  if i == 0: Tree[T](elem: x, left: t.left, right: t.right)
  else:
    let half = w div 2
    if i <= half: Tree[T](elem: t.elem, left: updateTree(half, t.left, i - 1, x), right: t.right)
    else: Tree[T](elem: t.elem, left: t.left, right: updateTree(half, t.right, i - 1 - half, x))

func get*[T](xs: SkewList[T]; i: int): Option[T] {.raises: [].} =
  ## Element at index `i` (0 is the head); none when out of range.
  if i < 0 or i >= xs.size: return none(T)
  var offset = i
  for e in items(xs.spine):
    if offset < e.weight: return some(lookupTree(e.weight, e.tree, offset))
    offset -= e.weight
  none(T)

func updated*[T](xs: SkewList[T]; i: int; x: T): Option[SkewList[T]] {.raises: [].} =
  ## A copy with index `i` replaced; none when out of range. Shares every untouched tree.
  if i < 0 or i >= xs.size: return none(SkewList[T])
  var before: seq[Entry[T]]
  var offset = i
  var cur = xs.spine
  while not cur.isEmpty:
    let e = cur.head.get
    if offset < e.weight:
      var spine = cur.tail.cons(Entry[T](weight: e.weight, tree: updateTree(e.weight, e.tree, offset, x)))
      for j in countdown(before.high, 0):
        spine = spine.cons(before[j])
      return some(SkewList[T](spine: spine, size: xs.size))
    offset -= e.weight
    before.add e
    cur = cur.tail
  none(SkewList[T])

func toSeq*[T](xs: SkewList[T]): seq[T] {.raises: [].} =
  var cur = xs
  while not cur.isEmpty:
    result.add cur.head.get
    cur = cur.tail

func fromSeq*[T](items: openArray[T]): SkewList[T] {.raises: [].} =
  var acc = emptySkew[T]()
  for i in countdown(items.high, 0):
    acc = acc.cons(items[i])
  acc

func weights*[T](xs: SkewList[T]): seq[int] {.raises: [].} =
  ## Sizes of the trees in the spine, front first.
  for e in items(xs.spine):
    result.add e.weight

func invariantsHold*[T](xs: SkewList[T]): bool {.raises: [].} =
  ## Weights are 2^k - 1, non-decreasing, strictly increasing after the first two, and they sum to len.
  let ws = xs.weights
  var total = 0
  for i, w in ws:
    if ((w + 1) and w) != 0: return false
    if i >= 1 and w < ws[i - 1]: return false
    if i >= 2 and w == ws[i - 1]: return false
    total += w
  total == xs.size
```

```nim
## Persistent string trie: a set of words stored as a tree of characters.
##
## Each node has a flag "a word ends here" and children sorted by character. `insert` copies the
## nodes along the word (one per character) and shares every other branch. `contains` costs
## O(length of the word); `keysWithPrefix` walks to the prefix and lists the words below it in
## sorted (byte-wise) order. Recursion depth equals the word length (a release build handles words of
## tens of thousands of characters, a debug build about 2,000). Use it for autocompletion and prefix search; use `hamt` or `rb_tree`
## when you only need whole-key lookup.

type
  Node = ref object
    terminal: bool
    kids: seq[(char, Node)]   ## sorted by char, one entry per char
  Trie* = object
    root: Node
    count: int

func emptyTrie*(): Trie {.raises: [].} =
  Trie()

func len*(t: Trie): int {.raises: [].} =
  ## Number of distinct words.
  t.count

func isEmpty*(t: Trie): bool {.raises: [].} =
  t.count == 0

func childIndex(n: Node; c: char): int =
  ## Index of `c` in `n.kids`, or -1.
  for i, kid in n.kids:
    if kid[0] == c: return i
    if kid[0] > c: return -1
  -1

func walk(root: Node; s: string): Node =
  ## The node reached by `s`, or nil.
  var n = root
  for c in s:
    if n.isNil: return nil
    let i = childIndex(n, c)
    if i < 0: return nil
    n = n.kids[i][1]
  n

func contains*(t: Trie; word: string): bool {.raises: [].} =
  let n = walk(t.root, word)
  not n.isNil and n.terminal

func hasPrefix*(t: Trie; prefix: string): bool {.raises: [].} =
  ## True when at least one stored word starts with `prefix` (the word itself counts).
  let n = walk(t.root, prefix)
  not n.isNil and (n.terminal or n.kids.len > 0)

func insertAt(n: Node; word: string; i: int): Node =
  let base = if n.isNil: Node() else: n
  if i == word.len: return Node(terminal: true, kids: base.kids)
  let c = word[i]
  var kids = base.kids
  let at = childIndex(base, c)
  if at >= 0:
    kids[at] = (c, insertAt(base.kids[at][1], word, i + 1))
  else:
    var pos = kids.len
    for j, kid in kids:
      if kid[0] > c:
        pos = j
        break
    kids.insert((c, insertAt(nil, word, i + 1)), pos)
  Node(terminal: base.terminal, kids: kids)

func insert*(t: Trie; word: string): Trie {.raises: [].} =
  ## Adds `word`; adding a word that is already present gives an equal trie.
  if t.contains(word): t
  else: Trie(root: insertAt(t.root, word, 0), count: t.count + 1)

func collect(n: Node; prefix: string; into: var seq[string]) =
  if n.terminal: into.add prefix
  for kid in n.kids:
    collect(kid[1], prefix & kid[0], into)

func keysWithPrefix*(t: Trie; prefix: string): seq[string] {.raises: [].} =
  ## Every stored word that starts with `prefix`, in sorted order. The empty prefix lists all words.
  let n = walk(t.root, prefix)
  if not n.isNil:
    collect(n, prefix, result)

func toSeq*(t: Trie): seq[string] {.raises: [].} =
  t.keysWithPrefix("")

func fromSeq*(words: openArray[string]): Trie {.raises: [].} =
  var t = emptyTrie()
  for w in words:
    t = t.insert(w)
  t
```

```nim
## Persistent union-find (disjoint sets) built on a persistent map.
##
## The classic imperative version keeps parents in an array and compresses paths while it finds,
## giving near-constant amortized time but destroying the old state. Here the parent and rank
## tables are `RbMap`s, so `union` returns a new structure and every earlier version stays
## usable (backtracking, undo, speculative merges). Union by rank alone bounds a root path by
## log2(n), so `find` is O(log n * log n) with the map lookups; `findCompress` also returns the
## compressed structure, which you must keep to benefit. Use it when you need old versions;
## use an array with path compression when only the latest state matters and speed counts.

import std/options
import nimcs/ds/rb_tree

type
  UnionFind* = object
    parent: RbMap[int, int]
    rank: RbMap[int, int]
    sets: int

func emptyUnionFind*(): UnionFind {.raises: [].} =
  UnionFind()

func components*(u: UnionFind): int {.raises: [].} =
  ## Number of disjoint sets among the elements seen so far.
  u.sets

func len*(u: UnionFind): int {.raises: [].} =
  ## Number of elements seen so far.
  u.parent.len

func contains*(u: UnionFind; x: int): bool {.raises: [].} =
  u.parent.contains(x)

func add*(u: UnionFind; x: int): UnionFind {.raises: [].} =
  ## Registers `x` as a singleton set; no change when it is already known.
  if u.contains(x): u
  else: UnionFind(parent: u.parent.put(x, x), rank: u.rank.put(x, 0), sets: u.sets + 1)

func parentOf(u: UnionFind; x: int): int =
  let p = u.parent.get(x)
  if p.isSome: p.get else: x

func find*(u: UnionFind; x: int): int {.raises: [].} =
  ## The representative of the set of `x`; an unknown element is its own representative.
  var cur = x
  while true:
    let p = u.parentOf(cur)
    if p == cur: return cur
    cur = p

func findCompress*(u: UnionFind; x: int): (int, UnionFind) {.raises: [].} =
  ## Like `find`, and also returns the structure with every node on the path pointing at the root.
  let root = u.find(x)
  var parent = u.parent
  var cur = x
  while cur != root and parent.get(cur).isSome:
    let p = parent.get(cur).get
    if p != root: parent = parent.put(cur, root)
    cur = p
  (root, UnionFind(parent: parent, rank: u.rank, sets: u.sets))

func rankOf(u: UnionFind; x: int): int =
  let r = u.rank.get(x)
  if r.isSome: r.get else: 0

func union*(u: UnionFind; a, b: int): UnionFind {.raises: [].} =
  ## Merges the sets of `a` and `b` (adding unknown elements first); idempotent.
  let base = u.add(a).add(b)
  let ra = base.find(a)
  let rb = base.find(b)
  if ra == rb: return base
  let rka = base.rankOf(ra)
  let rkb = base.rankOf(rb)
  if rka < rkb:
    UnionFind(parent: base.parent.put(ra, rb), rank: base.rank, sets: base.sets - 1)
  elif rkb < rka:
    UnionFind(parent: base.parent.put(rb, ra), rank: base.rank, sets: base.sets - 1)
  else:
    UnionFind(parent: base.parent.put(rb, ra), rank: base.rank.put(ra, rka + 1), sets: base.sets - 1)

func same*(u: UnionFind; a, b: int): bool {.raises: [].} =
  u.find(a) == u.find(b)

func pathLength*(u: UnionFind; x: int): int {.raises: [].} =
  ## Number of parent links from `x` to its representative.
  var cur = x
  while true:
    let p = u.parentOf(cur)
    if p == cur: return result
    cur = p
    inc result
```

```nim
## Zippers: a cursor into an immutable list or binary tree.
##
## A zipper is the data structure turned inside out around one focus: the part you have passed
## is kept in reverse, ready to be put back. Moving the focus and replacing the focused element
## are O(1); rebuilding the whole structure costs one step per level you went down. Nothing is
## mutated: every move or edit gives a new zipper that shares the rest. Use it for editors,
## parsers that backtrack and tree rewriting where "change this place and keep everything else"
## is the operation; use plain recursion when you transform every node.

import std/options
import nimcs/ds/cons_list

type
  ListZipper*[T] = object
    before: ConsList[T]     ## elements left of the focus, nearest first
    focus: T
    after: ConsList[T]      ## elements right of the focus, nearest first

  Tree*[T] = object
    node: Node[T]           ## nil is the empty tree
  Node[T] = ref object
    value: T
    left, right: Tree[T]

  Direction = enum
    goLeft, goRight
  Crumb[T] = object
    dir: Direction          ## which child the focus is
    value: T                ## the parent's value
    other: Tree[T]          ## the sibling subtree
  TreeZipper*[T] = object
    focus: Tree[T]
    trail: ConsList[Crumb[T]]

# ---- list zipper ------------------------------------------------------------------------------

func zipList*[T](items: openArray[T]): Option[ListZipper[T]] {.raises: [].} =
  ## A zipper focused on the first element; none for an empty list.
  if items.len == 0: none(ListZipper[T])
  else: some(ListZipper[T](before: emptyList[T](), focus: items[0],
    after: fromSeq(items.toOpenArray(1, items.high))))

func focus*[T](z: ListZipper[T]): T {.raises: [].} =
  z.focus

func moveRight*[T](z: ListZipper[T]): Option[ListZipper[T]] {.raises: [].} =
  let next = z.after.head
  if next.isNone: none(ListZipper[T])
  else: some(ListZipper[T](before: z.before.cons(z.focus), focus: next.get, after: z.after.tail))

func moveLeft*[T](z: ListZipper[T]): Option[ListZipper[T]] {.raises: [].} =
  let prev = z.before.head
  if prev.isNone: none(ListZipper[T])
  else: some(ListZipper[T](before: z.before.tail, focus: prev.get, after: z.after.cons(z.focus)))

func setFocus*[T](z: ListZipper[T]; x: T): ListZipper[T] {.raises: [].} =
  ListZipper[T](before: z.before, focus: x, after: z.after)

func modify*[T](z: ListZipper[T]; f: proc(x: T): T {.noSideEffect, raises: [].}): ListZipper[T] {.raises: [].} =
  z.setFocus(f(z.focus))

func toSeq*[T](z: ListZipper[T]): seq[T] {.raises: [].} =
  ## The whole list, rebuilt.
  z.before.reverse.toSeq & @[z.focus] & z.after.toSeq

func position*[T](z: ListZipper[T]): int {.raises: [].} =
  ## Index of the focus.
  z.before.len

# ---- binary tree ------------------------------------------------------------------------------

func leaf*[T](): Tree[T] {.raises: [].} =
  Tree[T]()

func branch*[T](left: Tree[T]; value: T; right: Tree[T]): Tree[T] {.raises: [].} =
  Tree[T](node: Node[T](value: value, left: left, right: right))

func isLeaf*[T](t: Tree[T]): bool {.raises: [].} =
  t.node.isNil

func value*[T](t: Tree[T]): Option[T] {.raises: [].} =
  if t.isLeaf: none(T) else: some(t.node.value)

func `==`*[T](a, b: Tree[T]): bool {.raises: [].} =
  if a.isLeaf or b.isLeaf: a.isLeaf and b.isLeaf
  else: a.node.value == b.node.value and a.node.left == b.node.left and a.node.right == b.node.right

func toSeq*[T](t: Tree[T]): seq[T] {.raises: [].} =
  ## In-order traversal.
  if t.isLeaf: return
  result = t.node.left.toSeq & @[t.node.value] & t.node.right.toSeq

func zipTree*[T](t: Tree[T]): TreeZipper[T] {.raises: [].} =
  TreeZipper[T](focus: t, trail: emptyList[Crumb[T]]())

func focusTree*[T](z: TreeZipper[T]): Tree[T] {.raises: [].} =
  z.focus

func downLeft*[T](z: TreeZipper[T]): Option[TreeZipper[T]] {.raises: [].} =
  ## Moves to the left child; none at a leaf.
  if z.focus.isLeaf: none(TreeZipper[T])
  else:
    let n = z.focus.node
    some(TreeZipper[T](focus: n.left,
      trail: z.trail.cons(Crumb[T](dir: goLeft, value: n.value, other: n.right))))

func downRight*[T](z: TreeZipper[T]): Option[TreeZipper[T]] {.raises: [].} =
  if z.focus.isLeaf: none(TreeZipper[T])
  else:
    let n = z.focus.node
    some(TreeZipper[T](focus: n.right,
      trail: z.trail.cons(Crumb[T](dir: goRight, value: n.value, other: n.left))))

func up*[T](z: TreeZipper[T]): Option[TreeZipper[T]] {.raises: [].} =
  ## Moves to the parent, putting the (possibly edited) focus back; none at the root.
  let crumb = z.trail.head
  if crumb.isNone: none(TreeZipper[T])
  else:
    let c = crumb.get
    let rebuilt =
      case c.dir
      of goLeft: branch(z.focus, c.value, c.other)
      of goRight: branch(c.other, c.value, z.focus)
    some(TreeZipper[T](focus: rebuilt, trail: z.trail.tail))

func replace*[T](z: TreeZipper[T]; t: Tree[T]): TreeZipper[T] {.raises: [].} =
  ## Swaps the focused subtree for `t`.
  TreeZipper[T](focus: t, trail: z.trail)

func modify*[T](z: TreeZipper[T]; f: proc(x: T): T {.noSideEffect, raises: [].}): TreeZipper[T] {.raises: [].} =
  ## Applies `f` to the value at the focus; a focused leaf has no value and stays as it is.
  if z.focus.isLeaf: z
  else:
    let n = z.focus.node
    z.replace(branch(n.left, f(n.value), n.right))

func rebuild*[T](z: TreeZipper[T]): Tree[T] {.raises: [].} =
  ## Goes up to the root and returns the whole tree.
  var cur = z
  while true:
    let parent = cur.up
    if parent.isNone: return cur.focus
    cur = parent.get

func depth*[T](z: TreeZipper[T]): int {.raises: [].} =
  ## Number of steps down from the root.
  z.trail.len
```

```nim
## Algebraic data types: a closed set of shapes as an object variant (ADR-NCK-0002 S2, S3).
##
## `Expr` is an arithmetic expression tree: a number, a negation, or a sum, product or quotient of
## two sub-expressions. Every routine over it is a `case` on `kind` with one branch per shape and
## no `else`, so adding a shape to `ExprKind` makes the compiler list every routine that must learn
## about it. Nodes are `ref` to immutable data (S3: `ref` only for recursion); nothing here mutates
## a node after construction. `eval` is total: arithmetic that cannot be done (division by zero,
## `int` overflow) is an `EvalError` value, never an exception.

import nimcs/fp/result

type
  ExprKind* = enum
    ekNum, ekNeg, ekAdd, ekMul, ekDiv

  Expr* = ref object
    case kind*: ExprKind
    of ekNum:
      value*: int
    of ekNeg:
      operand*: Expr
    of ekAdd, ekMul, ekDiv:
      left*, right*: Expr

  EvalError* = enum
    divideByZero, overflow

func num*(n: int): Expr {.raises: [].} = Expr(kind: ekNum, value: n)
func neg*(e: Expr): Expr {.raises: [].} = Expr(kind: ekNeg, operand: e)
func add*(a, b: Expr): Expr {.raises: [].} = Expr(kind: ekAdd, left: a, right: b)
func mul*(a, b: Expr): Expr {.raises: [].} = Expr(kind: ekMul, left: a, right: b)
func divide*(a, b: Expr): Expr {.raises: [].} = Expr(kind: ekDiv, left: a, right: b)

func `==`*(a, b: Expr): bool {.raises: [].} =
  ## Structural equality (the default for `ref` would compare addresses).
  case a.kind
  of ekNum: b.kind == ekNum and a.value == b.value
  of ekNeg: b.kind == ekNeg and a.operand == b.operand
  of ekAdd: b.kind == ekAdd and a.left == b.left and a.right == b.right
  of ekMul: b.kind == ekMul and a.left == b.left and a.right == b.right
  of ekDiv: b.kind == ekDiv and a.left == b.left and a.right == b.right

func addChecked(a, b: int): Result[int, EvalError] {.raises: [].} =
  if (b > 0 and a > high(int) - b) or (b < 0 and a < low(int) - b): err(int, overflow)
  else: ok(a + b, EvalError)

func mulChecked(a, b: int): Result[int, EvalError] {.raises: [].} =
  if a == 0 or b == 0: return ok(0, EvalError)
  let tooBig =
    if a > 0:
      (if b > 0: a > high(int) div b else: b < low(int) div a)
    else:
      (if b > 0: a < low(int) div b else: a < high(int) div b)
  if tooBig: err(int, overflow) else: ok(a * b, EvalError)

func divChecked(a, b: int): Result[int, EvalError] {.raises: [].} =
  if b == 0: err(int, divideByZero)
  elif a == low(int) and b == -1: err(int, overflow)
  else: ok(a div b, EvalError)

func evalWith(e: Expr; op: proc(a, b: int): Result[int, EvalError] {.noSideEffect, raises: [].}):
    Result[int, EvalError] {.raises: [].}

func eval*(e: Expr): Result[int, EvalError] {.raises: [].} =
  ## The value of `e`, or the first error met (left operand before right).
  case e.kind
  of ekNum:
    ok(e.value, EvalError)
  of ekNeg:
    let inner = eval(e.operand)
    if inner.isErr: inner
    elif inner.value == low(int): err(int, overflow)
    else: ok(-inner.value, EvalError)
  of ekAdd: evalWith(e, addChecked)
  of ekMul: evalWith(e, mulChecked)
  of ekDiv: evalWith(e, divChecked)

func evalWith(e: Expr; op: proc(a, b: int): Result[int, EvalError] {.noSideEffect, raises: [].}):
    Result[int, EvalError] {.raises: [].} =
  ## Evaluates both operands of a binary node (left first) and combines them with `op`.
  ## Precondition: `e.kind` is `ekAdd`, `ekMul` or `ekDiv` (only `eval` calls this).
  let l = eval(e.left)
  if l.isErr: return l
  let r = eval(e.right)
  if r.isErr: return r
  op(l.value, r.value)

func size*(e: Expr): int {.raises: [].} =
  ## Number of nodes.
  case e.kind
  of ekNum: 1
  of ekNeg: 1 + size(e.operand)
  of ekAdd, ekMul, ekDiv: 1 + size(e.left) + size(e.right)

func show*(e: Expr): string {.raises: [].} =
  ## Fully parenthesised text, e.g. `(1 + (2 * 3))`; a negation is `neg(...)`, so that
  ## `neg(num(1))` and `num(-1)` print differently (`show` is injective on trees).
  case e.kind
  of ekNum: $e.value
  of ekNeg: "neg(" & show(e.operand) & ")"
  of ekAdd: "(" & show(e.left) & " + " & show(e.right) & ")"
  of ekMul: "(" & show(e.left) & " * " & show(e.right) & ")"
  of ekDiv: "(" & show(e.left) & " / " & show(e.right) & ")"

func `$`*(e: Expr): string {.raises: [].} = show(e)

func isNum(e: Expr; n: int): bool {.raises: [].} =
  e.kind == ekNum and e.value == n

func simplify*(e: Expr): Expr {.raises: [].} =
  ## Rewrites bottom-up: constant folding when it cannot overflow, `0 + x`, `x + 0`, `1 * x`,
  ## `x * 1` and `x / 1` disappear. `--x` is deliberately kept unless `x` is a number: `-x`
  ## overflows for the smallest `int`, so dropping a double negation could turn an error into a value. `eval(simplify(e)) == eval(e)`, and simplifying twice
  ## gives the same tree as simplifying once.
  case e.kind
  of ekNum:
    e
  of ekNeg:
    let x = simplify(e.operand)
    if x.kind == ekNum and x.value != low(int): num(-x.value)
    else: neg(x)
  of ekAdd:
    let a = simplify(e.left)
    let b = simplify(e.right)
    if a.isNum(0): b
    elif b.isNum(0): a
    elif a.kind == ekNum and b.kind == ekNum and addChecked(a.value, b.value).isOk:
      num(a.value + b.value)
    else: add(a, b)
  of ekMul:
    let a = simplify(e.left)
    let b = simplify(e.right)
    if a.isNum(1): b
    elif b.isNum(1): a
    elif a.kind == ekNum and b.kind == ekNum and mulChecked(a.value, b.value).isOk:
      num(a.value * b.value)
    else: mul(a, b)
  of ekDiv:
    let a = simplify(e.left)
    let b = simplify(e.right)
    if b.isNum(1): a
    else: divide(a, b)
```

```nim
## Idempotence: doing it twice is the same as doing it once (ADR-NCK-0002 S4, S6).
##
## An operation `f` is idempotent when `f(f(x)) == f(x)` for every `x`. That is what makes a retry
## safe: a client that does not know whether its request arrived can send it again. This module
## holds four small idempotent operations and the law checker they share:
## `normalizeSpaces` (a normal form), `setInsert` (add to a sorted set), `upsertByKey` (insert or
## replace by key), and `apply` on a `Ledger` (a state transition guarded by an idempotency key,
## "apply this command at most once", where a reused key with a different command is an error).
## Every state is a value; nothing is mutated in place.

import std/algorithm
import nimcs/fp/result

func isIdempotentAt*[T](f: proc(x: T): T {.noSideEffect, raises: [].}; x: T): bool {.raises: [].} =
  ## True when `f(f(x)) == f(x)`. Use it as the body of a property test.
  f(f(x)) == f(x)

func normalizeSpaces*(s: string): string {.raises: [].} =
  ## Removes leading and trailing spaces and turns every run of spaces into a single space.
  var pendingSpace = false
  for c in s:
    if c == ' ':
      pendingSpace = result.len > 0
    else:
      if pendingSpace:
        result.add ' '
        pendingSpace = false
      result.add c

func setInsert*(xs: seq[int]; x: int): seq[int] {.raises: [].} =
  ## `xs` must be sorted and without duplicates; the result is too, and contains `x` exactly once.
  let at = xs.lowerBound(x)
  if at < xs.len and xs[at] == x:
    return xs
  result = xs[0 ..< at]
  result.add x
  result.add xs[at .. ^1]

type
  Entry* = object
    key*: string
    value*: int

func upsertByKey*(entries: seq[Entry]; key: string; value: int): seq[Entry] {.raises: [].} =
  ## Sets the value of `key`: the first entry with that key takes `value`, any further entries
  ## with the same key are dropped, and a missing key is appended. The result has exactly one
  ## entry for `key` even when the input had duplicates; other keys keep their order.
  result = newSeqOfCap[Entry](entries.len + 1)
  var found = false
  for e in entries:
    if e.key != key:
      result.add e
    elif not found:
      result.add Entry(key: key, value: value)
      found = true
  if not found:
    result.add Entry(key: key, value: value)

type
  Command* = object
    key*: string      ## idempotency key: a retry of the same request carries the same key
    amount*: int

  Ledger* = object
    ## The balance and, for each key already applied, the command that was applied.
    balance*: int
    applied*: seq[Command]   ## sorted by key, one command per key

  ApplyError* = enum
    keyConflict   ## the key was used before for a different command: a client bug, not a retry

func initLedger*(): Ledger {.raises: [].} =
  Ledger(balance: 0, applied: @[])

func `==`*(a, b: Command): bool {.raises: [].} =
  a.key == b.key and a.amount == b.amount

func `==`*(a, b: Ledger): bool {.raises: [].} =
  a.balance == b.balance and a.applied == b.applied

func findKey(l: Ledger; key: string): int {.raises: [].} =
  ## Index of the first applied command whose key is not below `key` (binary search).
  var lo = 0
  var hi = l.applied.len
  while lo < hi:
    let mid = (lo + hi) div 2
    if l.applied[mid].key < key: lo = mid + 1 else: hi = mid
  lo

func hasApplied*(l: Ledger; key: string): bool {.raises: [].} =
  let at = l.findKey(key)
  at < l.applied.len and l.applied[at].key == key

func apply*(l: Ledger; c: Command): Result[Ledger, ApplyError] {.raises: [].} =
  ## Adds `c.amount` to the balance the first time `c.key` is seen. The same command again
  ## (same key, same amount) is a retry and returns the same ledger. The same key with a
  ## different amount is `keyConflict`: it is reported, never silently ignored.
  ## Precondition: the balance stays within `int`.
  let at = l.findKey(c.key)
  if at < l.applied.len and l.applied[at].key == c.key:
    if l.applied[at] == c: return ok(l, ApplyError)
    return err(Ledger, keyConflict)
  var next = Ledger(balance: l.balance + c.amount, applied: l.applied[0 ..< at])
  next.applied.add c
  next.applied.add l.applied[at .. ^1]
  ok(next, ApplyError)

func applyAll*(l: Ledger; commands: openArray[Command]): Result[Ledger, ApplyError] {.raises: [].} =
  ## Applies the commands in order and stops at the first conflict.
  var cur = l
  for c in commands:
    let r = cur.apply(c)
    if r.isErr:
      return r
    cur = r.value
  ok(cur, ApplyError)
```

```nim
## Copy-and-update of value objects (ADR-NCK-0002 S3, S4).
##
## A `Cart` is a plain value: "changing" it means building a new `Cart` and leaving the old one
## valid, so every earlier version can still be read, compared or restored. Nim copies objects and
## sequences on assignment, which is what makes this safe; a `sink` parameter lets the compiler move
## the argument instead of copying it when the caller no longer needs it. The module is a worked
## example of the pattern: each update is a `func` that takes the old value and returns the new one.

import nimcs/fp/result

type
  CartError* = enum
    badQuantity, priceConflict

  Item* = object
    sku*: string
    qty*: int
    unitCents*: int

  Cart* = object
    ## Items in the order they were first added; at most one entry per `sku`.
    items*: seq[Item]

func initCart*(): Cart {.raises: [].} =
  Cart(items: @[])

func indexOf(items: seq[Item]; sku: string): int {.raises: [].} =
  result = -1
  for i, it in items:
    if it.sku == sku:
      return i

func added*(cart: sink Cart; item: Item): Result[Cart, CartError] {.raises: [].} =
  ## A cart with `item` added; the quantity is summed when the `sku` is already there.
  ## `item.qty` must be at least 1 (`badQuantity`), and an item whose `sku` is already in the
  ## cart must carry the same unit price (`priceConflict`): the cart never guesses which price is meant.
  ## `cart` is `sink`: a caller who keeps using the old cart gets a copy, one who does not gets a move.
  if item.qty < 1:
    return err(Cart, badQuantity)
  var next = cart
  let at = indexOf(next.items, item.sku)
  if at < 0:
    next.items.add item
  elif next.items[at].unitCents != item.unitCents:
    return err(Cart, priceConflict)
  else:
    next.items[at].qty += item.qty
  ok(next, CartError)

func withQty*(cart: sink Cart; sku: string; qty: int): Result[Cart, CartError] {.raises: [].} =
  ## A cart where `sku` has exactly `qty` units (`qty` at least 1, else `badQuantity`); a `sku`
  ## that is not in the cart is left alone. Setting the same quantity twice is the same as
  ## setting it once.
  if qty < 1:
    return err(Cart, badQuantity)
  var next = cart
  let at = indexOf(next.items, sku)
  if at >= 0:
    next.items[at].qty = qty
  ok(next, CartError)

func removed*(cart: sink Cart; sku: string): Cart {.raises: [].} =
  ## A cart without `sku`. Removing an absent `sku` changes nothing, so removing twice equals once.
  result = Cart(items: @[])
  for it in cart.items:
    if it.sku != sku:
      result.items.add it

func totalCents*(cart: Cart): int {.raises: [].} =
  ## Sum of `qty * unitCents` over the items. Precondition: the sum fits in an `int`.
  for it in cart.items:
    result += it.qty * it.unitCents

func `==`*(a, b: Cart): bool {.raises: [].} =
  a.items == b.items
```

```nim
## Lazy streams: sequences that compute their elements only when asked (ADR-NCK-0002 S3, S4).
##
## A `Stream[T]` is an immutable value holding a function that, when pulled, returns either "done"
## or "this element and the rest of the stream". `map`, `filter`, `take` and `takeWhile` build a new
## stream without computing anything and without building a `seq`; only `toSeq(limit)` walks the
## stream. Because a stream never changes, it can be walked twice with the same result, and an
## infinite stream (`iterate`) is safe as long as it is cut with `take` or `toSeq`'s limit.

type
  StreamStep[T] = object
    case hasValue: bool
    of true:
      head: T
      rest: Stream[T]
    of false:
      discard

  Stream*[T] = object
    pull: proc(): StreamStep[T] {.noSideEffect, raises: [].}

func endStep[T](): StreamStep[T] {.raises: [].} =
  StreamStep[T](hasValue: false)

func stepOf[T](head: T; rest: Stream[T]): StreamStep[T] {.raises: [].} =
  StreamStep[T](hasValue: true, head: head, rest: rest)

func emptyStream*[T](): Stream[T] {.raises: [].} =
  ## A stream with no elements.
  result = Stream[T](pull: proc(): StreamStep[T] {.noSideEffect, raises: [].} = endStep[T]())

type
  Shared[T] = ref object
    ## An immutable block of elements that all the stages of one `fromSeq` stream point to,
    ## so that moving to the next element copies a pointer, not the elements (ADR S3: `ref`
    ## only to immutable data).
    items: seq[T]

func fromShared[T](block0: Shared[T]; start: int): Stream[T] {.raises: [].} =
  result = Stream[T](pull: proc(): StreamStep[T] {.noSideEffect, raises: [].} =
    if start >= block0.items.len: endStep[T]()
    else: stepOf(block0.items[start], fromShared(block0, start + 1)))

func fromSeq*[T](xs: openArray[T]): Stream[T] {.raises: [].} =
  ## The stream of the elements of `xs`, in order. The elements are copied once, here.
  fromShared(Shared[T](items: @xs), 0)

func iterate*[T](seed: T; next: proc(x: T): T {.noSideEffect, raises: [].}): Stream[T] {.raises: [].} =
  ## The infinite stream `seed, next(seed), next(next(seed)), ...`. `next` is applied only when
  ## the element after `seed` is pulled, never ahead of need.
  result = Stream[T](pull: proc(): StreamStep[T] {.noSideEffect, raises: [].} =
    let rest = Stream[T](pull: proc(): StreamStep[T] {.noSideEffect, raises: [].} =
      iterate(next(seed), next).pull())
    stepOf(seed, rest))

func map*[T, U](s: Stream[T]; f: proc(x: T): U {.noSideEffect, raises: [].}): Stream[U] {.raises: [].} =
  ## Applies `f` to each element when it is reached.
  result = Stream[U](pull: proc(): StreamStep[U] {.noSideEffect, raises: [].} =
    let step = s.pull()
    if step.hasValue: stepOf(f(step.head), step.rest.map(f))
    else: endStep[U]())

func filter*[T](s: Stream[T]; keep: proc(x: T): bool {.noSideEffect, raises: [].}): Stream[T] {.raises: [].} =
  ## The elements for which `keep` holds. On an infinite stream with no match, pulling never returns.
  result = Stream[T](pull: proc(): StreamStep[T] {.noSideEffect, raises: [].} =
    var cur = s
    while true:
      let step = cur.pull()
      if not step.hasValue:
        return endStep[T]()
      if keep(step.head):
        return stepOf(step.head, step.rest.filter(keep))
      cur = step.rest
    endStep[T]())

func take*[T](s: Stream[T]; n: Natural): Stream[T] {.raises: [].} =
  ## At most the first `n` elements.
  result = Stream[T](pull: proc(): StreamStep[T] {.noSideEffect, raises: [].} =
    if n == 0:
      return endStep[T]()
    let step = s.pull()
    if step.hasValue: stepOf(step.head, step.rest.take(n - 1))
    else: endStep[T]())

func takeWhile*[T](s: Stream[T]; keep: proc(x: T): bool {.noSideEffect, raises: [].}): Stream[T] {.raises: [].} =
  ## The longest prefix whose elements all satisfy `keep`.
  result = Stream[T](pull: proc(): StreamStep[T] {.noSideEffect, raises: [].} =
    let step = s.pull()
    if step.hasValue and keep(step.head): stepOf(step.head, step.rest.takeWhile(keep))
    else: endStep[T]())

func toSeq*[T](s: Stream[T]; limit: Natural): seq[T] {.raises: [].} =
  ## Walks the stream and collects at most `limit` elements. The limit is required so that an
  ## infinite stream cannot hang the caller.
  var cur = s
  while result.len < limit:
    let step = cur.pull()
    if not step.hasValue:
      break
    result.add step.head
    cur = step.rest
```

```nim
## Working with `std/options` without sentinels (ADR-NCK-0002 S2).
##
## `Option[T]` says "there may be no value". The standard library already gives `map`, `flatMap`,
## `filter`, `get(default)` and `isSome`; this module adds the pieces that are missing when options
## meet each other or meet `Result`: turn absence into a reason (`okOr`), pick the first present
## value (`orElse`), combine two options (`both`), and flip a list of options into an option of a
## list (`sequence`). Reach for it whenever "not found" is an expected answer, not an error.

import std/options
import nimcs/fp/result

func okOr*[T, E](o: Option[T]; reason: E): Result[T, E] {.raises: [].} =
  ## Absence becomes the given error; presence becomes `ok`.
  if o.isSome: Result[T, E](isOk: true, value: o.get)
  else: Result[T, E](isOk: false, error: reason)

func toOption*[T, E](r: Result[T, E]): Option[T] {.raises: [].} =
  ## Forgets why a result failed.
  if r.isOk: some(r.value) else: none(T)

func orElse*[T](a, b: Option[T]): Option[T] {.raises: [].} =
  ## The first option that holds a value (left-biased). `none` is the identity, so this is a
  ## monoid on options.
  if a.isSome: a else: b

func both*[A, B](a: Option[A]; b: Option[B]): Option[(A, B)] {.raises: [].} =
  ## `some` of the pair only when both hold a value.
  if a.isSome and b.isSome: some((a.get, b.get)) else: none((A, B))

func sequence*[T](xs: openArray[Option[T]]): Option[seq[T]] {.raises: [].} =
  ## `some` of all the values, in order, when every element holds one; otherwise `none`.
  var values = newSeqOfCap[T](xs.len)
  for x in xs:
    if x.isNone:
      return none(seq[T])
    values.add x.get
  some(values)

func catSome*[T](xs: openArray[Option[T]]): seq[T] {.raises: [].} =
  ## Keeps the values that are present and drops the absent ones, preserving order.
  result = newSeqOfCap[T](xs.len)
  for x in xs:
    if x.isSome:
      result.add x.get

func firstSome*[T](xs: openArray[Option[T]]): Option[T] {.raises: [].} =
  ## The first element that holds a value, or `none` for an empty or all-absent input.
  for x in xs:
    if x.isSome:
      return x
  none(T)
```

```nim
## `Result[T, E]`: a value or the reason there is none (ADR-NCK-0002 S2).
##
## A small, dependency-free version of what `results` (Status) offers, so that every module and
## every dataset record compiles with the standard library alone. The names (`ok`, `err`, `isOk`,
## `map`, `flatMap`, `mapErr`, `valueOr`) resemble those of the `results` package, but the API is
## not compatible: here `ok` and `err` take a type argument (`ok(1, string)`, `err(int, "e")`),
## and reading `.value` of an error, or `.error` of a success, raises `FieldDefect` instead of
## following the `results` rules. Check `isOk` first, or leave the railway with `valueOr`.
## A program that already uses `results` should keep using it and not mix the two types.

type
  Result*[T, E] = object
    case isOk*: bool
    of true:
      value*: T
    of false:
      error*: E

func ok*[T, E](v: T; _: typedesc[E]): Result[T, E] {.raises: [].} =
  Result[T, E](isOk: true, value: v)

func err*[T, E](_: typedesc[T]; e: E): Result[T, E] {.raises: [].} =
  Result[T, E](isOk: false, error: e)

func isErr*[T, E](r: Result[T, E]): bool {.raises: [].} = not r.isOk

func map*[T, E, U](r: Result[T, E]; f: proc(x: T): U {.noSideEffect, raises: [].}): Result[U, E] {.raises: [].} =
  ## Functor law (spec FP-RESULT-01): r.map(identity) == r; r.map(f).map(g) == r.map(g ∘ f).
  if r.isOk: Result[U, E](isOk: true, value: f(r.value))
  else: Result[U, E](isOk: false, error: r.error)

func flatMap*[T, E, U](r: Result[T, E];
    f: proc(x: T): Result[U, E] {.noSideEffect, raises: [].}): Result[U, E] {.raises: [].} =
  ## The railway: the first error stops the chain (spec FP-RESULT-02).
  if r.isOk: f(r.value)
  else: Result[U, E](isOk: false, error: r.error)

func mapErr*[T, E, F](r: Result[T, E]; f: proc(e: E): F {.noSideEffect, raises: [].}): Result[T, F] {.raises: [].} =
  if r.isOk: Result[T, F](isOk: true, value: r.value)
  else: Result[T, F](isOk: false, error: f(r.error))

func valueOr*[T, E](r: Result[T, E]; fallback: T): T {.raises: [].} =
  if r.isOk: r.value else: fallback

func `==`*[T, E](a, b: Result[T, E]): bool {.raises: [].} =
  if a.isOk != b.isOk: false
  elif a.isOk: a.value == b.value
  else: a.error == b.error
```

```nim
## Adapter as a function between two types.
##
## The OO pattern wraps an object with an incompatible interface so that existing client code can
## use it. In Nim the interface is a type, so the adapter is a `func` that converts the old shape to
## the new one; adapting a source of values is mapping that func over it. Here a legacy schedule
## source returns "HH:MM" strings and the new code wants `Minutes` since midnight. Use it at the
## boundary where a foreign shape enters; do not let the foreign shape leak further in.

import nimcs/fp/result

type
  Minutes* = distinct int

  AdaptError* = enum
    aeBadLength, aeBadSeparator, aeBadDigit, aeOutOfRange

  LegacySource* = proc(): seq[string] {.noSideEffect, raises: [].}

func `==`*(a, b: Minutes): bool {.borrow.}

func digit(c: char): int {.raises: [].} =
  if c in {'0' .. '9'}: ord(c) - ord('0') else: -1

func fromLegacy*(s: string): Result[Minutes, AdaptError] {.raises: [].} =
  ## Parses "HH:MM"; every malformed input is a specific error, never an exception.
  if s.len != 5:
    err(Minutes, aeBadLength)
  elif s[2] != ':':
    err(Minutes, aeBadSeparator)
  else:
    let (a, b, c, d) = (digit(s[0]), digit(s[1]), digit(s[3]), digit(s[4]))
    if a < 0 or b < 0 or c < 0 or d < 0:
      err(Minutes, aeBadDigit)
    else:
      let h = a * 10 + b
      let m = c * 10 + d
      if h > 23 or m > 59: err(Minutes, aeOutOfRange)
      else: ok(Minutes(h * 60 + m), AdaptError)

func toLegacy*(m: Minutes): string {.raises: [].} =
  ## Inverse of `fromLegacy` on `0 .. 1439`.
  let v = int(m)
  let h = v div 60
  let mm = v mod 60
  $(h div 10) & $(h mod 10) & ":" & $(mm div 10) & $(mm mod 10)

func adaptAll*(src: LegacySource): Result[seq[Minutes], AdaptError] {.raises: [].} =
  ## Adapts a whole source; the first bad entry stops the conversion.
  var acc: seq[Minutes] = @[]
  for s in src():
    let r = fromLegacy(s)
    if r.isErr:
      return err(seq[Minutes], r.error)
    acc.add(r.value)
  ok(acc, AdaptError)
```

```nim
## Anti-corruption layer: translate a foreign model at the border so it never leaks inward.
##
## Another system's model (a supplier's order message) has its own words, codes and number formats,
## and it changes when they decide. If its types reach into your code, every change of theirs is a
## change of yours, and its mistakes (a status code you never meant to support) become your states.
## The layer is the only place that knows both. It is a pair of functions per foreign version: one
## from the foreign record to your `Order`, built through the same smart constructor as every
## order of your own, and one back; your code takes `Order` and cannot be handed a foreign record
## (the compiler refuses it). A new foreign version is a new pair, and nothing inward moves.
## Refusals are values with a reason and a position, not zeros and defaults. Use it where a model
## you do not control meets one you do; do not use it between two parts of your own model.

import nimcs/fp/result
export result

type
  OrderStatus* = enum
    osActive, osShipped, osCancelled

  Cents* = distinct int

  Order* = object
    ## The inner model: a non-empty id and a total that is never negative.
    id*: string
    status*: OrderStatus
    total*: Cents

  TranslateError* = enum
    teEmptyId, teUnknownStatus, teBadAmount

  ForeignOrderV1* = object
    ## The supplier's first format: a status letter and a decimal amount as text, "12.50".
    reference*: string
    statusCode*: string
    amount*: string

  ForeignOrderV2* = object
    ## Their second format: status words and an integer number of cents.
    orderId*: string
    state*: string
    minorUnits*: int

  Refusal* = tuple[index: int, error: TranslateError]

  Translated* = tuple[orders: seq[Order], refused: seq[Refusal]]

func `==`*(a, b: Cents): bool {.borrow.}
func `<`*(a, b: Cents): bool {.borrow.}
func `$`*(c: Cents): string {.borrow.}

func initOrder*(id: string; status: OrderStatus; total: int): Result[Order, TranslateError] {.raises: [].} =
  ## The one place the inner invariants are checked; every translator goes through it.
  if id.len == 0:
    err(Order, teEmptyId)
  elif total < 0:
    err(Order, teBadAmount)
  else:
    ok(Order(id: id, status: status, total: Cents(total)), TranslateError)

func canShip*(o: Order): bool {.raises: [].} =
  ## Inner business rule. It names only inner types, so a foreign record cannot reach it.
  o.status == osActive and int(o.total) > 0

func parseAmountV1(s: string): Result[int, TranslateError] {.raises: [].} =
  ## "digits.dd" with 1 to 9 whole digits (the length is checked first, so no overflow).
  let dot = s.len - 3
  if dot < 1 or dot > 9 or s[dot] != '.':
    return err(int, teBadAmount)
  var cents = 0
  for i, c in s:
    if i != dot:
      if c notin {'0' .. '9'}:
        return err(int, teBadAmount)
      cents = cents * 10 + (ord(c) - ord('0'))
  ok(cents, TranslateError)

func statusV1(code: string): Result[OrderStatus, TranslateError] {.raises: [].} =
  case code
  of "A": ok(osActive, TranslateError)
  of "S": ok(osShipped, TranslateError)
  of "X": ok(osCancelled, TranslateError)
  else: err(OrderStatus, teUnknownStatus)

func statusV2(word: string): Result[OrderStatus, TranslateError] {.raises: [].} =
  case word
  of "ACTIVE": ok(osActive, TranslateError)
  of "SHIPPED": ok(osShipped, TranslateError)
  of "CANCELLED": ok(osCancelled, TranslateError)
  else: err(OrderStatus, teUnknownStatus)

func fromV1*(f: ForeignOrderV1): Result[Order, TranslateError] {.raises: [].} =
  ## Checks in a fixed order: id, status, amount; the first problem is the error.
  if f.reference.len == 0:
    return err(Order, teEmptyId)
  let status = statusV1(f.statusCode)
  if status.isErr:
    return err(Order, status.error)
  let amount = parseAmountV1(f.amount)
  if amount.isErr:
    return err(Order, amount.error)
  initOrder(f.reference, status.value, amount.value)

func fromV2*(f: ForeignOrderV2): Result[Order, TranslateError] {.raises: [].} =
  if f.orderId.len == 0:
    return err(Order, teEmptyId)
  let status = statusV2(f.state)
  if status.isErr:
    return err(Order, status.error)
  initOrder(f.orderId, status.value, f.minorUnits)

func toV1*(o: Order): ForeignOrderV1 {.raises: [].} =
  let cents = int(o.total)
  let frac = cents mod 100
  let code = case o.status
    of osActive: "A"
    of osShipped: "S"
    of osCancelled: "X"
  ForeignOrderV1(reference: o.id, statusCode: code,
    amount: $(cents div 100) & "." & $(frac div 10) & $(frac mod 10))

func toV2*(o: Order): ForeignOrderV2 {.raises: [].} =
  let word = case o.status
    of osActive: "ACTIVE"
    of osShipped: "SHIPPED"
    of osCancelled: "CANCELLED"
  ForeignOrderV2(orderId: o.id, state: word, minorUnits: int(o.total))

func translateAll*[F](xs: seq[F]; translate: proc(f: F): Result[Order, TranslateError] {.noSideEffect, raises: [].}
    ): Translated {.raises: [].} =
  ## A bad record does not stop the batch and is not dropped silently: it is listed with its index.
  result = (orders: @[], refused: @[])
  for i, x in xs:
    let r = translate(x)
    if r.isOk:
      result.orders.add r.value
    else:
      result.refused.add (index: i, error: r.error)
```

```nim
## Chain of Responsibility: a list of "maybe handle it" functions; the first `some` wins.
##
## The OO pattern links handler objects, each holding a reference to its successor and deciding to
## handle or pass on. In Nim a handler is `proc(request): Option[Response]`, a chain is a plain
## `seq` of them, and "pass it on" is simply moving to the next element. `orElse` composes two
## handlers into one, which makes handlers a monoid (associative, with `never` as identity), so
## chains can be nested or built in pieces. Unhandled is a `Result` error, not a nil. Use it for
## approvals, middleware, parsers that try alternatives, and fallbacks. The example approves
## expense claims by the lowest authority whose limit covers the amount.

import std/options
import nimcs/fp/result

type
  Handler*[Req, Resp] = proc(request: Req): Option[Resp] {.noSideEffect, raises: [].}

  Unhandled* = object
    ## No handler in the chain accepted the request.

  Claim* = object
    amount*: int
    category*: string

  Approval* = object
    by*: string
    amount*: int

func `==`*(a, b: Approval): bool {.raises: [].} = a.by == b.by and a.amount == b.amount
func `$`*(a: Approval): string {.raises: [].} = a.by & "@" & $a.amount

func never*[Req, Resp](request: Req): Option[Resp] {.raises: [].} =
  ## The handler that accepts nothing; the identity of `orElse`.
  none(Resp)

func firstSome*[Req, Resp](chain: openArray[Handler[Req, Resp]]; request: Req): Option[Resp] {.raises: [].} =
  ## Asks the handlers in order and returns the first answer. Handlers after the one that answered
  ## are not called.
  for h in chain:
    let r = h(request)
    if r.isSome: return r
  none(Resp)

func handle*[Req, Resp](chain: openArray[Handler[Req, Resp]];
                        request: Req): Result[Resp, Unhandled] {.raises: [].} =
  let r = firstSome(chain, request)
  if r.isSome: ok(r.get, Unhandled) else: err(Resp, Unhandled())

func orElse*[Req, Resp](first, second: Handler[Req, Resp]): Handler[Req, Resp] {.raises: [].} =
  ## One handler that tries `first`, then `second`.
  result = proc(request: Req): Option[Resp] {.noSideEffect, raises: [].} =
    let r = first(request)
    if r.isSome: r else: second(request)

func within*(name: string; limit: int): Handler[Claim, Approval] {.raises: [].} =
  ## Approves claims up to `limit` (inclusive); passes on anything larger or non-positive.
  result = proc(c: Claim): Option[Approval] {.noSideEffect, raises: [].} =
    if c.amount > 0 and c.amount <= limit: some(Approval(by: name, amount: c.amount))
    else: none(Approval)

func onlyCategory*(h: Handler[Claim, Approval]; category: string): Handler[Claim, Approval] {.raises: [].} =
  ## Restricts a handler to one category of claim; other categories are passed on.
  result = proc(c: Claim): Option[Approval] {.noSideEffect, raises: [].} =
    if c.category == category: h(c) else: none(Approval)

func authorityChain*(): seq[Handler[Claim, Approval]] {.raises: [].} =
  ## Clerk up to 100, manager up to 1000, director up to 10000.
  @[within("clerk", 100), within("manager", 1000), within("director", 10000)]
```

```nim
## Command: an edit is a value; undo is another value.
##
## Positions and lengths are byte offsets into a UTF-8 text. A command that would cut a multi-byte
## character (a position on a continuation byte) or insert invalid UTF-8 is refused, so a valid
## document stays valid and `inverse` always describes the edit that was applied.
##
## The OO pattern wraps a request in an object with `execute` and `undo` so it can be queued,
## logged and reversed. In Nim a command is plain data (an object variant), `apply` is a pure
## function from document and command to a new document, and undo is the inverse command, computed
## from the document as it was before the edit. The editor keeps two stacks of inverse/forward
## commands. Use it when operations must be replayed, logged, undone or sent elsewhere; when you
## only need "go back to an earlier state", keep the old values instead (see `memento`).

import std/unicode
import nimcs/fp/result

type
  CmdKind* = enum
    ckInsert, ckDelete

  Cmd* = object
    ## Insert `text` before index `pos`, or delete `len` characters starting at `pos`.
    case kind*: CmdKind
    of ckInsert:
      pos*: int
      text*: string
    of ckDelete:
      at*: int
      len*: int

  EditError* = enum
    eeOutOfRange, eeNotCharBoundary, eeInvalidUtf8, eeNothingToUndo, eeNothingToRedo

  Editor* = object
    text*: string
    undoStack*: seq[Cmd]   ## inverse commands, most recent last
    redoStack*: seq[Cmd]   ## forward commands that were undone, most recent last

func insertCmd*(pos: int; text: string): Cmd {.raises: [].} =
  Cmd(kind: ckInsert, pos: pos, text: text)

func deleteCmd*(at, len: int): Cmd {.raises: [].} =
  Cmd(kind: ckDelete, at: at, len: len)

func `==`*(a, b: Cmd): bool {.raises: [].} =
  if a.kind != b.kind: return false
  case a.kind
  of ckInsert: a.pos == b.pos and a.text == b.text
  of ckDelete: a.at == b.at and a.len == b.len

func `==`*(a, b: Editor): bool {.raises: [].} =
  a.text == b.text and a.undoStack == b.undoStack and a.redoStack == b.redoStack

func `$`*(c: Cmd): string {.raises: [].} =
  case c.kind
  of ckInsert: "insert(" & $c.pos & ", " & c.text & ")"
  of ckDelete: "delete(" & $c.at & ", " & $c.len & ")"

func initEditor*(text: string): Editor {.raises: [].} =
  Editor(text: text, undoStack: @[], redoStack: @[])

func onBoundary(doc: string; p: int): bool {.raises: [].} =
  ## `p` (already in `0 .. doc.len`) does not fall inside a multi-byte character.
  p == doc.len or (ord(doc[p]) and 0xC0) != 0x80

func checkInsert(doc: string; c: Cmd): Result[bool, EditError] {.raises: [].} =
  if c.pos < 0 or c.pos > doc.len: return err(bool, eeOutOfRange)
  if not onBoundary(doc, c.pos): return err(bool, eeNotCharBoundary)
  if validateUtf8(c.text) != -1: return err(bool, eeInvalidUtf8)
  ok(true, EditError)

func checkDelete(doc: string; c: Cmd): Result[bool, EditError] {.raises: [].} =
  if c.at < 0 or c.len < 0 or c.at > doc.len - c.len: return err(bool, eeOutOfRange)
  if not onBoundary(doc, c.at) or not onBoundary(doc, c.at + c.len):
    return err(bool, eeNotCharBoundary)
  ok(true, EditError)

func apply*(doc: string; cmd: Cmd): Result[string, EditError] {.raises: [].} =
  ## The pure transition. A command that points outside the document, into the middle of a
  ## character, or inserts invalid UTF-8 is an error, not a clamp.
  case cmd.kind
  of ckInsert:
    let c = checkInsert(doc, cmd)
    if c.isErr: return err(string, c.error)
    ok(doc[0 ..< cmd.pos] & cmd.text & doc[cmd.pos .. ^1], EditError)
  of ckDelete:
    let c = checkDelete(doc, cmd)
    if c.isErr: return err(string, c.error)
    ok(doc[0 ..< cmd.at] & doc[cmd.at + cmd.len .. ^1], EditError)

func inverse*(doc: string; cmd: Cmd): Result[Cmd, EditError] {.raises: [].} =
  ## The command that undoes `cmd` when run on the document produced from `doc`.
  ## It needs `doc` because a delete must remember what it removed. Same validity rules as `apply`.
  case cmd.kind
  of ckInsert:
    let c = checkInsert(doc, cmd)
    if c.isErr: return err(Cmd, c.error)
    ok(deleteCmd(cmd.pos, cmd.text.len), EditError)
  of ckDelete:
    let c = checkDelete(doc, cmd)
    if c.isErr: return err(Cmd, c.error)
    ok(insertCmd(cmd.at, doc[cmd.at ..< cmd.at + cmd.len]), EditError)

func exec*(ed: Editor; cmd: Cmd): Result[Editor, EditError] {.raises: [].} =
  ## Runs a new command: pushes its inverse on the undo stack and clears redo.
  let next = apply(ed.text, cmd)
  if next.isErr: return err(Editor, next.error)
  let inv = inverse(ed.text, cmd)
  if inv.isErr: return err(Editor, inv.error)
  ok(Editor(text: next.value, undoStack: ed.undoStack & inv.value, redoStack: @[]), EditError)

func undo*(ed: Editor): Result[Editor, EditError] {.raises: [].} =
  if ed.undoStack.len == 0: return err(Editor, eeNothingToUndo)
  let inv = ed.undoStack[^1]
  let back = apply(ed.text, inv)
  if back.isErr: return err(Editor, back.error)
  # The redo command is the inverse of the inverse, taken on the current text.
  let fwd = inverse(ed.text, inv)
  if fwd.isErr: return err(Editor, fwd.error)
  ok(Editor(text: back.value, undoStack: ed.undoStack[0 ..< ed.undoStack.len - 1],
            redoStack: ed.redoStack & fwd.value), EditError)

func redo*(ed: Editor): Result[Editor, EditError] {.raises: [].} =
  if ed.redoStack.len == 0: return err(Editor, eeNothingToRedo)
  let fwd = ed.redoStack[^1]
  let next = apply(ed.text, fwd)
  if next.isErr: return err(Editor, next.error)
  let inv = inverse(ed.text, fwd)
  if inv.isErr: return err(Editor, inv.error)
  ok(Editor(text: next.value, undoStack: ed.undoStack & inv.value,
            redoStack: ed.redoStack[0 ..< ed.redoStack.len - 1]), EditError)

func replay*(start: string; log: openArray[Cmd]): Result[string, EditError] {.raises: [].} =
  ## Folds a command log over a document; stops at the first failing command.
  var doc = start
  for c in log:
    let r = apply(doc, c)
    if r.isErr: return r
    doc = r.value
  ok(doc, EditError)
```

```nim
## Facade as a module that exports a small API over several private steps.
##
## The OO pattern puts one simple class in front of a set of subsystem classes. In Nim the module
## boundary is the facade: the steps (`tokenize`, `countWords`, ...) are not exported, and the
## exported surface is `normalizeText` and `summarize`. Use it when callers need one or two
## answers and should not know the order or number of internal steps. No class is needed.

import std/[algorithm, options, tables]

type
  Summary* = object
    words*: int
    unique*: int
    longest*: Option[string]
    top*: seq[(string, int)]

func isWordChar(c: char): bool {.raises: [].} =
  c in {'a' .. 'z', '0' .. '9'}

func lowerAscii(c: char): char {.raises: [].} =
  if c in {'A' .. 'Z'}: char(ord(c) + 32) else: c

func normalizeText*(text: string): string {.raises: [].} =
  ## Lower-cases ASCII letters, turns every other character into a space, collapses runs of
  ## spaces and trims. Idempotent.
  var pendingSpace = false
  for raw in text:
    let c = lowerAscii(raw)
    if isWordChar(c):
      if pendingSpace and result.len > 0:
        result.add(' ')
      pendingSpace = false
      result.add(c)
    else:
      pendingSpace = true

func tokenize(normalized: string): seq[string] =
  var current = ""
  for c in normalized:
    if c == ' ':
      if current.len > 0:
        result.add(current)
        current = ""
    else:
      current.add(c)
  if current.len > 0:
    result.add(current)

func countWords(words: seq[string]): seq[(string, int)] =
  ## Sorted by count descending, then word ascending, so the order never depends on hashing.
  var counts = initTable[string, int]()
  for w in words:
    counts[w] = counts.getOrDefault(w, 0) + 1
  for w, n in counts:
    result.add((w, n))
  result.sort(proc(a, b: (string, int)): int =
    if a[1] != b[1]: cmp(b[1], a[1]) else: cmp(a[0], b[0]))

func summarize*(text: string; topN: int = 3): Summary {.raises: [].} =
  let words = tokenize(normalizeText(text))
  let counts = countWords(words)
  var longest = none(string)
  for w in words:
    if longest.isNone or w.len > longest.get.len:
      longest = some(w)
  Summary(words: words.len, unique: counts.len, longest: longest,
          top: counts[0 ..< min(max(topN, 0), counts.len)])
```

```nim
## Object capability: authority only by reference (ADR-NCK-0002).
##
## A capability is a value that names a resource and, by existing, grants the right to use it in
## specific ways. There is no ambient authority: no function here reaches a file, a global or a
## clock on its own; every operation takes the capability (and the `Store` it acts on) as an
## argument, so reading a signature tells you what a routine may touch. `FileCap` is sealed (a
## private field and `{.requiresInit.}`), so code outside this module cannot write
## `FileCap(rights: ...)` or declare an empty one; the only ways to get one are `rootCap` and the
## attenuations `readOnly`, `restrict` and `narrow`, and each of them returns a capability that
## permits no more than the one it came from. Delegation is passing the value.
##
## Honest limit: Nim cannot hide `rootCap`, the one function that creates authority from nothing.
## The convention is the powerbox: call it only at the program's edge (`main`), and hand narrower
## capabilities inward. A review (or a text search) for `rootCap` finds every place that can
## create authority. The `Store` is a plain persistent value standing for the resource; a real
## program applies the same shape to a directory, a socket or a device.

import std/[options, strutils]
import nimcs/ds/hamt
import nimcs/fp/result

type
  Right* = enum
    rtRead, rtWrite

  CapError* = enum
    ceDenied      ## the capability lacks the right
    ceOutside     ## the path is not below the capability's prefix
    ceBadPath     ## empty, absolute, or containing an empty, `.` or `..` segment
    ceNotFound

  FileCap* {.requiresInit.} = object
    ## Rights and a path prefix (whole segments). The empty prefix covers every path.
    held: set[Right]
    base: seq[string]

  Store* = Hamt[string, string]

func segments(path: string): Option[seq[string]] =
  ## The segments of a relative path, or `none` if any segment is empty, `.` or `..`.
  if path.len == 0: return none(seq[string])
  let parts = path.split('/')
  for p in parts:
    if p.len == 0 or p == "." or p == "..": return none(seq[string])
  some(parts)

func rootCap*(rights: set[Right]): FileCap {.raises: [].} =
  ## Authority from nothing: call it once, at the program's edge.
  FileCap(held: rights, base: @[])

func rights*(c: FileCap): set[Right] {.raises: [].} = c.held

func prefix*(c: FileCap): string {.raises: [].} = c.base.join("/")

func `==`*(a, b: FileCap): bool {.raises: [].} = a.held == b.held and a.base == b.base

func restrict*(c: FileCap; keep: set[Right]): FileCap {.raises: [].} =
  ## Keeps only the rights in `keep`; it can drop rights, never add them.
  FileCap(held: c.held * keep, base: c.base)

func readOnly*(c: FileCap): FileCap {.raises: [].} = c.restrict({rtRead})

func narrow*(c: FileCap; sub: string): Result[FileCap, CapError] {.raises: [].} =
  ## A capability for the directory `sub` below this one's prefix (`sub` is a relative path).
  let s = segments(sub)
  if s.isNone: return err(FileCap, ceBadPath)
  ok(FileCap(held: c.held, base: c.base & s.get), CapError)

func check(c: FileCap; right: Right; path: string): Result[bool, CapError] =
  let s = segments(path)
  if s.isNone: return err(bool, ceBadPath)
  if right notin c.held: return err(bool, ceDenied)
  if s.get.len <= c.base.len: return err(bool, ceOutside)
  for i in 0 ..< c.base.len:
    if s.get[i] != c.base[i]: return err(bool, ceOutside)
  ok(true, CapError)

func permits*(c: FileCap; right: Right; path: string): bool {.raises: [].} =
  c.check(right, path).isOk

func emptyStore*(): Store {.raises: [].} = emptyHamt[string, string]()

func read*(store: Store; c: FileCap; path: string): Result[string, CapError] {.raises: [].} =
  let allowed = c.check(rtRead, path)
  if allowed.isErr: return err(string, allowed.error)
  let found = store.get(path)
  if found.isNone: err(string, ceNotFound) else: ok(found.get, CapError)

func write*(store: Store; c: FileCap; path, data: string): Result[Store, CapError] {.raises: [].} =
  ## Returns the new store; the argument is unchanged.
  let allowed = c.check(rtWrite, path)
  if allowed.isErr: return err(Store, allowed.error)
  ok(store.put(path, data), CapError)
```

```nim
## Parallel change (expand, migrate, contract): change a shape without a moment when callers break.
##
## A change to something many callers use (a column, a field, a function's argument) is done in
## three steps that each leave every caller working: expand (the new shape exists next to the old
## one and every writer keeps both in step), migrate (fill the new shape for data written before,
## move callers one at a time) and contract (remove the old shape once nothing reads it). Here a
## person's name moves from one legacy text, "Family, Given", to a `Name` with two parts. A record
## holds both columns; writers through either door set both, readers fall back to translating the
## other column, `backfill` fills rows that predate the change, and `contract` is a function that
## refuses to drop the legacy column while any row would lose its only copy. Use it when callers
## cannot all be changed in one commit or one deploy; it costs a period with two shapes, so give the
## period an end.

import std/options
import nimcs/fp/result
export result

type
  NameError* = enum
    neEmptyGiven, neEmptyFamily, neComma, neNoSeparator

  Name* = object
    given*, family*: string

  Record* = object
    ## During expand both fields may be set. A row written before the change has only `legacy`;
    ## after contract only `current` is set.
    legacy*: Option[string]
    current*: Option[Name]

  Store* = seq[Record]

  ContractError* = object
    firstUnmigrated*: int   ## index of the first row with no current name

const Separator = ", "

func initName*(given, family: string): Result[Name, NameError] {.raises: [].} =
  ## A part may be neither empty nor contain a comma, so the legacy text splits back uniquely.
  if given.len == 0:
    err(Name, neEmptyGiven)
  elif family.len == 0:
    err(Name, neEmptyFamily)
  elif ',' in given or ',' in family:
    err(Name, neComma)
  else:
    ok(Name(given: given, family: family), NameError)

func formatLegacy*(n: Name): string {.raises: [].} = n.family & Separator & n.given

func parseLegacy*(s: string): Result[Name, NameError] {.raises: [].} =
  ## Splits at the first separator; every other shape is an error, never an exception.
  var at = -1
  for i in 0 ..< s.len - 1:
    if s[i] == ',' and s[i + 1] == ' ':
      at = i
      break
  if at < 0:
    err(Name, neNoSeparator)
  else:
    initName(s[at + Separator.len .. ^1], s[0 ..< at])

func writeCurrent*(n: Name): Record {.raises: [].} =
  ## The new door keeps the old column in step so legacy readers stay right.
  Record(legacy: some(formatLegacy(n)), current: some(n))

func writeLegacy*(s: string): Result[Record, NameError] {.raises: [].} =
  ## The old door keeps the new column in step; a text that does not parse is refused here, not
  ## stored where only one reader could use it.
  let parsed = parseLegacy(s)
  if parsed.isOk:
    ok(Record(legacy: some(s), current: some(parsed.value)), NameError)
  else:
    err(Record, parsed.error)

func readCurrent*(r: Record): Option[Name] {.raises: [].} =
  if r.current.isSome:
    r.current
  elif r.legacy.isSome:
    let parsed = parseLegacy(r.legacy.get)
    if parsed.isOk: some(parsed.value) else: none(Name)
  else:
    none(Name)

func readLegacy*(r: Record): Option[string] {.raises: [].} =
  ## Kept after contract only to show that an old caller would still get the same answer.
  if r.legacy.isSome:
    r.legacy
  elif r.current.isSome:
    some(formatLegacy(r.current.get))
  else:
    none(string)

func backfill*(r: Record): Record {.raises: [].} =
  ## Fills the current name of a row written before the change. Idempotent; a text that does not
  ## parse stays as it is, for a person to look at.
  if r.current.isNone:
    Record(legacy: r.legacy, current: readCurrent(r))
  else:
    r

func contract*(s: Store): Result[Store, ContractError] {.raises: [].} =
  ## Drops the legacy column, but only when no row would lose its only copy of the name.
  for i, r in s:
    if r.current.isNone:
      return err(Store, ContractError(firstUnmigrated: i))
  var done: Store = @[]
  for r in s:
    done.add Record(legacy: none(string), current: r.current)
  ok(done, ContractError)
```

```nim
## Parser combinators: small parsers are values, and bigger parsers are functions of them.
##
## A `Parser[T]` takes the input and a position and returns either a value with the position
## after it, or a `ParseError` saying where and what was expected. Nothing is thrown and nothing
## is mutated, so a parser is a pure function you can test on any string. Combinators (`thenP`,
## `orElse`, `many`, `chainl1`, `between`) build larger parsers from smaller ones, and the
## grammar of arithmetic below reads like its own specification. Use it for small formats where a
## parser generator is too heavy; for large or ambiguous grammars use a generator. Alternatives
## are tried left to right and the first success wins (no backtracking into a chosen branch).

import nimcs/fp/result

type
  ParseError* = object
    pos*: int
    expected*: string

  Parsed*[T] = object
    value*: T
    next*: int  ## position just after what was consumed

  Parser*[T] = proc(input: string; pos: int): Result[Parsed[T], ParseError] {.noSideEffect, raises: [].}

  CharTest* = proc(c: char): bool {.noSideEffect, raises: [].}

  BinOp* = enum
    opAdd, opSub, opMul

  ExprKind* = enum
    ekNum, ekBin

  Expr* = ref ExprNode
  ExprNode* = object
    ## An immutable tree: build it with `num` and `bin`, never assign to a field.
    case kind*: ExprKind
    of ekNum:
      value*: int
    of ekBin:
      op*: BinOp
      left*, right*: Expr

  EvalError* = enum
    eeOutOfRange

const MaxLiteral* = 999_999_999
const MaxNesting* = 64      ## deepest parenthesis nesting `parseArithmetic` accepts
const MaxInputLen* = 1024   ## longest input `parseArithmetic` accepts, in bytes
const ValueLimit* = 2_147_483_648  ## intermediate results beyond +-2^31 are refused

# ── combinators ────────────────────────────────────────────────────────────

func satisfy*(test: CharTest; what: string): Parser[char] {.raises: [].} =
  ## One character that passes `test`; `what` names it in the error.
  proc(input: string; pos: int): Result[Parsed[char], ParseError] {.noSideEffect, raises: [].} =
    if pos >= 0 and pos < input.len and test(input[pos]):
      ok(Parsed[char](value: input[pos], next: pos + 1), ParseError)
    else:
      err(Parsed[char], ParseError(pos: pos, expected: what))

func charP*(c: char): Parser[char] {.raises: [].} =
  satisfy(proc(x: char): bool {.noSideEffect, raises: [].} = x == c, "'" & c & "'")

func digit*(): Parser[char] {.raises: [].} =
  satisfy(proc(x: char): bool {.noSideEffect, raises: [].} = x in {'0' .. '9'}, "a digit")

func mapP*[T, U](p: Parser[T]; f: proc(x: T): U {.noSideEffect, raises: [].}): Parser[U] {.raises: [].} =
  ## Changes the value of a successful parse.
  proc(input: string; pos: int): Result[Parsed[U], ParseError] {.noSideEffect, raises: [].} =
    let r = p(input, pos)
    if r.isOk: ok(Parsed[U](value: f(r.value.value), next: r.value.next), ParseError)
    else: err(Parsed[U], r.error)

func flatMapP*[T, U](p: Parser[T]; f: proc(x: T): Result[U, string] {.noSideEffect, raises: [].}): Parser[U] {.raises: [].} =
  ## Like `mapP`, but `f` may refuse the value; its message becomes the error at the start position.
  proc(input: string; pos: int): Result[Parsed[U], ParseError] {.noSideEffect, raises: [].} =
    let r = p(input, pos)
    if r.isErr: return err(Parsed[U], r.error)
    let mapped = f(r.value.value)
    if mapped.isOk: ok(Parsed[U](value: mapped.value, next: r.value.next), ParseError)
    else: err(Parsed[U], ParseError(pos: pos, expected: mapped.error))

func thenP*[A, B](p: Parser[A]; q: Parser[B]): Parser[(A, B)] {.raises: [].} =
  ## `p` then `q`; both values are kept.
  proc(input: string; pos: int): Result[Parsed[(A, B)], ParseError] {.noSideEffect, raises: [].} =
    let a = p(input, pos)
    if a.isErr: return err(Parsed[(A, B)], a.error)
    let b = q(input, a.value.next)
    if b.isErr: err(Parsed[(A, B)], b.error)
    else: ok(Parsed[(A, B)](value: (a.value.value, b.value.value), next: b.value.next), ParseError)

func orElse*[T](p, q: Parser[T]): Parser[T] {.raises: [].} =
  ## `p`'s result when it succeeds, otherwise `q`'s. When both fail, the error is the one that
  ## got further; when they failed at the same position, the expectations are joined with "or".
  proc(input: string; pos: int): Result[Parsed[T], ParseError] {.noSideEffect, raises: [].} =
    let a = p(input, pos)
    if a.isOk: return a
    let b = q(input, pos)
    if b.isOk: return b
    if a.error.pos > b.error.pos: err(Parsed[T], a.error)
    elif b.error.pos > a.error.pos: err(Parsed[T], b.error)
    elif a.error.expected == b.error.expected: err(Parsed[T], b.error)
    else: err(Parsed[T], ParseError(pos: a.error.pos, expected: a.error.expected & " or " & b.error.expected))

func many*[T](p: Parser[T]): Parser[seq[T]] {.raises: [].} =
  ## Zero or more repetitions; it never fails. A repetition that consumes nothing ends the loop,
  ## so a parser that can succeed on empty input cannot make it spin.
  proc(input: string; pos: int): Result[Parsed[seq[T]], ParseError] {.noSideEffect, raises: [].} =
    var items: seq[T]
    var cur = pos
    while true:
      let r = p(input, cur)
      if r.isErr or r.value.next <= cur: break
      items.add r.value.value
      cur = r.value.next
    ok(Parsed[seq[T]](value: items, next: cur), ParseError)

func many1*[T](p: Parser[T]): Parser[seq[T]] {.raises: [].} =
  ## One or more repetitions; the error is that of the first attempt.
  proc(input: string; pos: int): Result[Parsed[seq[T]], ParseError] {.noSideEffect, raises: [].} =
    let first = p(input, pos)
    if first.isErr: return err(Parsed[seq[T]], first.error)
    let rest = many(p)(input, first.value.next)
    if rest.isErr: return err(Parsed[seq[T]], rest.error)
    ok(Parsed[seq[T]](value: @[first.value.value] & rest.value.value, next: rest.value.next), ParseError)

func skipSpaces*(): Parser[int] {.raises: [].} =
  ## Skips blanks and returns how many; never fails.
  many(satisfy(proc(x: char): bool {.noSideEffect, raises: [].} = x == ' ', "a space")).mapP(
    proc(xs: seq[char]): int {.noSideEffect, raises: [].} = xs.len)

func token*[T](p: Parser[T]): Parser[T] {.raises: [].} =
  ## `p` followed by any blanks, whose count is dropped.
  proc(input: string; pos: int): Result[Parsed[T], ParseError] {.noSideEffect, raises: [].} =
    let r = p(input, pos)
    if r.isErr: return r
    let blanks = skipSpaces()(input, r.value.next)
    if blanks.isErr: return err(Parsed[T], blanks.error)
    ok(Parsed[T](value: r.value.value, next: blanks.value.next), ParseError)

func between*[O, T, C](open: Parser[O]; p: Parser[T]; close: Parser[C]): Parser[T] {.raises: [].} =
  ## `open`, then `p`, then `close`; keeps only `p`'s value.
  proc(input: string; pos: int): Result[Parsed[T], ParseError] {.noSideEffect, raises: [].} =
    let o = open(input, pos)
    if o.isErr: return err(Parsed[T], o.error)
    let inner = p(input, o.value.next)
    if inner.isErr: return inner
    let c = close(input, inner.value.next)
    if c.isErr: return err(Parsed[T], c.error)
    ok(Parsed[T](value: inner.value.value, next: c.value.next), ParseError)

func lazyP*[T](make: proc(): Parser[T] {.noSideEffect, raises: [].}): Parser[T] {.raises: [].} =
  ## Builds the parser only when it first runs, which lets a grammar rule refer to itself.
  proc(input: string; pos: int): Result[Parsed[T], ParseError] {.noSideEffect, raises: [].} =
    make()(input, pos)

func chainl1*[T, O](operand: Parser[T]; op: Parser[O];
                    combine: proc(o: O; l, r: T): T {.noSideEffect, raises: [].}): Parser[T] {.raises: [].} =
  ## `operand (op operand)*`, combined from the left: `1-2-3` is `(1-2)-3`. Once an operator has
  ## been read, a missing operand is an error rather than a silent stop.
  proc(input: string; pos: int): Result[Parsed[T], ParseError] {.noSideEffect, raises: [].} =
    let first = operand(input, pos)
    if first.isErr: return first
    var acc = first.value.value
    var cur = first.value.next
    while true:
      let o = op(input, cur)
      if o.isErr: break
      let rhs = operand(input, o.value.next)
      if rhs.isErr: return err(Parsed[T], rhs.error)
      acc = combine(o.value.value, acc, rhs.value.value)
      cur = rhs.value.next
    ok(Parsed[T](value: acc, next: cur), ParseError)

# ── the expression type ────────────────────────────────────────────────────

func `==`*(a, b: Expr): bool {.raises: [].} =
  ## Structural equality (the default for `ref` would compare addresses).
  if a.isNil or b.isNil: return a.isNil and b.isNil
  if a.kind != b.kind: return false
  case a.kind
  of ekNum: a.value == b.value
  of ekBin: a.op == b.op and a.left == b.left and a.right == b.right

func num*(v: range[0 .. MaxLiteral]): Expr {.raises: [].} =
  ## A literal. Out-of-range values raise a `RangeDefect`: callers can check the bound.
  Expr(kind: ekNum, value: v)

func bin*(op: BinOp; left, right: Expr): Expr {.raises: [].} =
  Expr(kind: ekBin, op: op, left: left, right: right)

func opChar(op: BinOp): char {.raises: [].} =
  case op
  of opAdd: '+'
  of opSub: '-'
  of opMul: '*'

func print*(e: Expr): string {.raises: [].} =
  ## Fully parenthesised, no spaces: `((1+2)*3)`. `parseArithmetic` reads it back to the same tree.
  case e.kind
  of ekNum: $e.value
  of ekBin: "(" & print(e.left) & $opChar(e.op) & print(e.right) & ")"

func printSpaced*(e: Expr): string {.raises: [].} =
  ## Like `print` with one blank between tokens: `( ( 1 + 2 ) * 3 )`.
  case e.kind
  of ekNum: $e.value
  of ekBin: "( " & printSpaced(e.left) & " " & $opChar(e.op) & " " & printSpaced(e.right) & " )"

func evaluate*(e: Expr): Result[int, EvalError] {.raises: [].} =
  ## Evaluates in `int`; an intermediate value beyond +-2^31 is `eeOutOfRange`, which also keeps
  ## every product inside 64 bits.
  case e.kind
  of ekNum: ok(e.value, EvalError)
  of ekBin:
    let l = evaluate(e.left)
    if l.isErr: return l
    let r = evaluate(e.right)
    if r.isErr: return r
    let v =
      case e.op
      of opAdd: l.value + r.value
      of opSub: l.value - r.value
      of opMul: l.value * r.value
    if abs(v) > ValueLimit: err(int, eeOutOfRange) else: ok(v, EvalError)

# ── the grammar ────────────────────────────────────────────────────────────
#   expr   = term   (('+' | '-') term)*
#   term   = factor ('*' factor)*
#   factor = number | '(' expr ')'

func exprP*(): Parser[Expr] {.raises: [].}

func numberP(): Parser[Expr] {.raises: [].} =
  token(many1(digit())).flatMapP(
    proc(ds: seq[char]): Result[Expr, string] {.noSideEffect, raises: [].} =
      if ds.len > 9:
        err(Expr, "a number of at most 9 digits")
      else:
        var n = 0
        for c in ds: n = n * 10 + (ord(c) - ord('0'))
        ok(num(n), string))

func combineOp(o: BinOp; l, r: Expr): Expr {.raises: [].} = bin(o, l, r)

func addOp(): Parser[BinOp] {.raises: [].} =
  let plus = token(charP('+')).mapP(proc(c: char): BinOp {.noSideEffect, raises: [].} = opAdd)
  let minus = token(charP('-')).mapP(proc(c: char): BinOp {.noSideEffect, raises: [].} = opSub)
  orElse(plus, minus)

func mulOp(): Parser[BinOp] {.raises: [].} =
  token(charP('*')).mapP(proc(c: char): BinOp {.noSideEffect, raises: [].} = opMul)

func factorP(): Parser[Expr] {.raises: [].} =
  orElse(numberP(), between(token(charP('(')), lazyP(exprP), token(charP(')'))))

func termP(): Parser[Expr] {.raises: [].} =
  chainl1(factorP(), mulOp(), combineOp)

func exprP*(): Parser[Expr] {.raises: [].} =
  chainl1(termP(), addOp(), combineOp)

func parseArithmetic*(input: string): Result[Expr, ParseError] {.raises: [].} =
  ## Parses the whole input (blanks allowed around tokens). Unconsumed input is an error at the
  ## position where it starts. Input longer than `MaxInputLen` or nested deeper than `MaxNesting`
  ## is refused with an error before parsing, because recursion depth (here and in `print`,
  ## `evaluate`, `==`) follows nesting and chain length. `exprP()` called directly has no limit.
  if input.len > MaxInputLen:
    return err(Expr, ParseError(pos: MaxInputLen, expected: "input of at most " & $MaxInputLen & " bytes"))
  var depth = 0
  for i, c in input:
    if c == '(':
      inc depth
      if depth > MaxNesting:
        return err(Expr, ParseError(pos: i, expected: "nesting of at most " & $MaxNesting & " levels"))
    elif c == ')' and depth > 0:
      dec depth
  let lead = skipSpaces()(input, 0)
  if lead.isErr: return err(Expr, lead.error)
  let r = exprP()(input, lead.value.next)
  if r.isErr: return err(Expr, r.error)
  if r.value.next != input.len:
    return err(Expr, ParseError(pos: r.value.next, expected: "end of input"))
  ok(r.value.value, ParseError)
