```nim
## Seam: a place where behaviour can be changed without editing the code at that place.
##
## Legacy code reaches for what it needs (a price list, a clock, a database) from inside, so it
## cannot be run, or tested, without all of it. A seam is a point where the call can be redirected:
## in functional Nim the simplest is a parameter, a proc the routine is handed (a *function seam*;
## a record of procs is the same idea for several operations). Making a seam must not change what the
## routine does, so the first test is old against new on the same inputs. With the seam in place a
## test supplies its own answers, and a pinned list of input and output pairs (a characterization)
## says whether a later change kept the behaviour nobody wrote down. Here a hard-wired price list
## becomes a seam. The old routine counted an unknown SKU as 0; the seam version says so instead
## of inventing a price, which is the one difference, shown by its own law. Use it before changing code
## you cannot yet test, and keep the default seam equal to the old wiring until the pins are green.

import std/options
import nimcs/fp/result
export result

type
  Seam* = proc(sku: string): Option[int] {.noSideEffect, raises: [].}
    ## Answers the price of a SKU in cents, or none when it does not know the SKU.

  PriceError* = object
    unknownSku*: string

  Total* = proc(skus: seq[string]): int {.noSideEffect, raises: [].}

  Pin* = tuple[input: seq[string], output: int]

  Pins* = seq[Pin]

func hardWiredPrice(sku: string): int {.raises: [].} =
  case sku
  of "apple": 120
  of "pear": 150
  of "fig": 300
  else: 0   # what the legacy routine did with a SKU it did not know

func discounted(sum, lines: int): int {.raises: [].} =
  ## Three or more lines earn a tenth off, rounded down.
  if lines >= 3: sum - sum div 10 else: sum

func legacyTotal*(skus: seq[string]): int {.raises: [].} =
  ## The routine before the seam: the price list is inside.
  var sum = 0
  for s in skus:
    sum += hardWiredPrice(s)
  discounted(sum, skus.len)

func defaultSeam*(): Seam {.raises: [].} =
  ## The old wiring as a seam: the same list, but an unknown SKU is none, not 0.
  proc(sku: string): Option[int] {.noSideEffect, raises: [].} =
    if sku in ["apple", "pear", "fig"]: some(hardWiredPrice(sku)) else: none(int)

func total*(prices: Seam; skus: seq[string]): Result[int, PriceError] {.raises: [].} =
  ## The same arithmetic with the lookup handed in; the first unknown SKU is the error.
  var sum = 0
  for s in skus:
    let p = prices(s)
    if p.isNone:
      return err(int, PriceError(unknownSku: s))
    sum += p.get
  ok(discounted(sum, skus.len), PriceError)

func pin*(f: Total; inputs: seq[seq[string]]): Pins {.raises: [].} =
  ## Records what `f` does now, input by input.
  for i in inputs:
    result.add (input: i, output: f(i))

func firstDifference*(pins: Pins; f: Total): Option[int] {.raises: [].} =
  ## The index of the first pinned input on which `f` no longer gives the pinned output.
  for i, p in pins:
    if f(p.input) != p.output:
      return some(i)
  none(int)

func holds*(pins: Pins; f: Total): bool {.raises: [].} = firstDifference(pins, f).isNone
```

```nim
## Strategy: the algorithm you swap is a function value.
##
## The OO pattern puts each interchangeable algorithm in its own class behind one interface so the
## caller can choose at run time. In Nim the interface is a proc type, the classes are procs (or
## closures made by a constructor func), and "choosing" is passing an argument. Here the varying
## part is how an order total is discounted; `checkout` never learns which rule it received. Use it
## when one step of a computation has several interchangeable implementations. When the choice is
## fixed at compile time, the proc can be passed as a generic parameter instead (`total2` below);
## that removes the closure but is not a promise of inlining.
##
## Prices are `Cents >= 0` (see `cents`); amounts near `high(int)` are handled without overflow.

import std/options

type
  Cents* = distinct int

  PriceRule* = proc(price: Cents): Cents {.noSideEffect, raises: [].}
    ## A strategy: maps a price to a price. The constructors below keep results in `0 .. price`.

func `==`*(a, b: Cents): bool {.borrow.}
func `<=`*(a, b: Cents): bool {.borrow.}
func `<`*(a, b: Cents): bool {.borrow.}
func `$`*(a: Cents): string {.borrow.}

func cents*(n: int): Option[Cents] {.raises: [].} =
  ## Smart constructor: a price is never negative.
  if n < 0: none(Cents) else: some(Cents(n))

func value*(c: Cents): int {.raises: [].} = int(c)

func noDiscount*(price: Cents): Cents {.raises: [].} =
  ## The identity strategy.
  price

func percentOff*(pct: int): PriceRule {.raises: [].} =
  ## Takes `pct` percent off, rounding the discount down. `pct` is clamped into 0..100.
  ## The discount is computed as `q*p + (r*p) div 100` for `price = 100*q + r`, which equals
  ## `(price*p) div 100` for non-negative prices without ever forming `price*p` (no overflow).
  let p = max(0, min(100, pct))
  result = proc(price: Cents): Cents {.noSideEffect, raises: [].} =
    let v = value(price)
    Cents(v - ((v div 100) * p + ((v mod 100) * p) div 100))

func flatOff*(amount: int): PriceRule {.raises: [].} =
  ## Takes a fixed amount off, never going below zero. A negative amount counts as zero.
  let a = max(0, amount)
  result = proc(price: Cents): Cents {.noSideEffect, raises: [].} =
    if value(price) <= a: Cents(0) else: Cents(value(price) - a)

func then*(first, second: PriceRule): PriceRule {.raises: [].} =
  ## Applies `first`, then `second` to its result.
  result = proc(price: Cents): Cents {.noSideEffect, raises: [].} =
    second(first(price))

func sumSaturating(items: openArray[Cents]): Cents {.raises: [].} =
  ## Sum of the items; a total beyond `high(int)` stays at `high(int)` instead of overflowing.
  var sum = 0
  for it in items:
    let x = value(it)
    sum = if x > 0 and sum > high(int) - x: high(int) else: sum + x
  Cents(sum)

func checkout*(items: openArray[Cents]; rule: PriceRule): Cents {.raises: [].} =
  ## The context: sums the items (saturating at `high(int)`), then lets the strategy decide the
  ## final price. Items are assumed non-negative (build them with `cents`).
  rule(sumSaturating(items))

func total2*[R](items: openArray[Cents]; rule: R): Cents {.raises: [].} =
  ## Same, with the strategy as a generic parameter: the rule's type is known at compile time, so
  ## no closure is required (whether the C compiler inlines the call is not guaranteed; measure).
  rule(sumSaturating(items))

func cheapest*(rules: openArray[PriceRule]; price: Cents): Cents {.raises: [].} =
  ## Best price over all strategies (no rules: the price itself).
  result = price
  for r in rules:
    let p = r(price)
    if p < result: result = p
```

```nim
## Tagless final: write the program once against an interface, choose the meaning by choosing a type.
##
## A program such as `dotProduct` is a generic function over a type `R` that satisfies `ExprSym`:
## it can make a literal and combine two values. It never says what `R` is. Instantiate it with
## `Eval` and you get the number, with `Show` the text, with `Size` a node count, with `Ast` a
## data tree. Compared with `free_interpreter` the program is not data you can inspect or
## rewrite, but there is no interpreter loop and no instruction type: adding an interpreter means
## adding a type and four small funcs, and adding an operation means adding a func to the concept
## and to each interpreter. Use it when the set of operations is stable and the set of
## interpretations grows.

type
  Eval* = distinct int     ## interpretation: the value
  Show* = distinct string  ## interpretation: fully parenthesised text
  Size* = distinct int     ## interpretation: number of nodes

  AstKind = enum
    akLit, akAdd, akMul, akNeg

  AstNode = object
    case kind: AstKind
    of akLit: n: int
    of akAdd, akMul:
      left, right: Ast
    of akNeg: inner: Ast

  Ast* = ref AstNode  ## interpretation: the program reified as an immutable tree

  ExprSym* = concept
    ## The interface a program is written against.
    proc lit(t: typedesc[Self]; n: int): Self
    proc add(a, b: Self): Self
    proc mul(a, b: Self): Self
    proc neg(a: Self): Self

# ── Eval ───────────────────────────────────────────────────────────────────

func lit*(t: typedesc[Eval]; n: int): Eval {.raises: [].} = Eval(n)
func add*(a, b: Eval): Eval {.raises: [].} = Eval(int(a) + int(b))
func mul*(a, b: Eval): Eval {.raises: [].} = Eval(int(a) * int(b))
func neg*(a: Eval): Eval {.raises: [].} = Eval(-int(a))
func value*(e: Eval): int {.raises: [].} = int(e)

# ── Show ───────────────────────────────────────────────────────────────────

func lit*(t: typedesc[Show]; n: int): Show {.raises: [].} = Show($n)
func add*(a, b: Show): Show {.raises: [].} = Show("(" & string(a) & "+" & string(b) & ")")
func mul*(a, b: Show): Show {.raises: [].} = Show("(" & string(a) & "*" & string(b) & ")")
func neg*(a: Show): Show {.raises: [].} = Show("-(" & string(a) & ")")
func text*(s: Show): string {.raises: [].} = string(s)

# ── Size ───────────────────────────────────────────────────────────────────

func lit*(t: typedesc[Size]; n: int): Size {.raises: [].} = Size(1)
func add*(a, b: Size): Size {.raises: [].} = Size(int(a) + int(b) + 1)
func mul*(a, b: Size): Size {.raises: [].} = Size(int(a) + int(b) + 1)
func neg*(a: Size): Size {.raises: [].} = Size(int(a) + 1)
func nodes*(s: Size): int {.raises: [].} = int(s)

# ── Ast (the initial encoding, for comparison) ─────────────────────────────

func lit*(t: typedesc[Ast]; n: int): Ast {.raises: [].} = Ast(kind: akLit, n: n)
func add*(a, b: Ast): Ast {.raises: [].} = Ast(kind: akAdd, left: a, right: b)
func mul*(a, b: Ast): Ast {.raises: [].} = Ast(kind: akMul, left: a, right: b)
func neg*(a: Ast): Ast {.raises: [].} = Ast(kind: akNeg, inner: a)

func evalAst*(a: Ast): int {.raises: [].} =
  ## Evaluates a reified tree; equals interpreting the program under `Eval`.
  case a.kind
  of akLit: a.n
  of akAdd: evalAst(a.left) + evalAst(a.right)
  of akMul: evalAst(a.left) * evalAst(a.right)
  of akNeg: -evalAst(a.inner)

func sizeAst*(a: Ast): int {.raises: [].} =
  case a.kind
  of akLit: 1
  of akAdd, akMul: sizeAst(a.left) + sizeAst(a.right) + 1
  of akNeg: sizeAst(a.inner) + 1

func printAst*(a: Ast): string {.raises: [].} =
  case a.kind
  of akLit: $a.n
  of akAdd: "(" & printAst(a.left) & "+" & printAst(a.right) & ")"
  of akMul: "(" & printAst(a.left) & "*" & printAst(a.right) & ")"
  of akNeg: "-(" & printAst(a.inner) & ")"

# ── programs: written once, for every interpretation ───────────────────────

func dotProduct*[R: ExprSym](pairs: openArray[(int, int)]): R {.raises: [].} =
  ## 0 + a1*b1 + a2*b2 + ..., left to right.
  result = lit(R, 0)
  for (a, b) in pairs:
    result = add(result, mul(lit(R, a), lit(R, b)))

func horner*[R: ExprSym](coeffs: openArray[int]; x: int): R {.raises: [].} =
  ## The polynomial with the given coefficients (highest degree first) at `x`, by Horner's rule.
  if coeffs.len == 0:
    return lit(R, 0)
  result = lit(R, coeffs[0])
  for i in 1 ..< coeffs.len:
    result = add(mul(result, lit(R, x)), lit(R, coeffs[i]))

func negated*[R: ExprSym](pairs: openArray[(int, int)]): R {.raises: [].} =
  ## A program built from another program: the negated dot product.
  neg(dotProduct[R](pairs))
```

